/* Generated by gen_packs.py from the original data files: pack "sm". */
MC.registerPack({"id":"sm","cards":[{"id":"27001a","name":"고스트 스파이더","en":"* Ghost-Spider","type":"hero","enc":false,"unique":true,"hp":10,"atk":2,"thw":1,"def":3,"hs":5,"tr":["WEB-WARRIOR"],"traits":["웹 워리어"],"text":"<i>어지러운 반사신경</i> - <b>반응:</b> 당신이 이벤트의 \"<b>난입</b>\" 또는 \"<b>반응</b>\" 능력을 해결한 후, 고스트 스파이더를 준비합니다. (페이즈마다 1회 제한.)"},{"id":"27001b","name":"그웬 스테이시","en":"* Gwen Stacy","type":"alter","enc":false,"unique":true,"hp":10,"rec":3,"hs":6,"tr":["CIVILIAN"],"traits":["시민"],"text":"<b>행동:</b> 당신의 버린 더미에서 멀티버스 티켓을 당신의 덱에 섞어 넣거나 조지 스테이시를 준비하는 것 중 하나를 선택합니다. (라운드마다 1회 제한.)"},{"id":"27002","name":"유령 발차기","en":"Ghost Kick","type":"event","enc":false,"unique":false,"cost":2,"res":"R","cls":"Hero","tr":["ATTACK"],"traits":["공격"],"text":"<b>히어로 반응</b><i>(공격)</i>: 고스트 스파이더가 기본 기능을 사용한 후, 적 하나에게 피해 6점을 입힙니다. (기본 기능 사용마다 최대 1장.)"},{"id":"27003","name":"부모의 지도","en":"Parental Guidance","type":"event","enc":false,"unique":false,"cost":0,"res":"Y","cls":"Hero","tr":[],"traits":[],"text":"<b>일상 행동</b>:\n- 조지 스테이시가 플레이 영역에 있다면, 당신의 손이나 버린 더미에서 이벤트 1장을 조지 스테이시에게 뒷면으로 장착합니다.\n- 조지 스테이시가 플레이 영역에 없다면, 당신의 덱과 버린 더미에서 그를 찾아 당신의 손에 더합니다. <i>(섞습니다.)</i>"},{"id":"27004","name":"환영 공중제비","en":"Phantom Flip","type":"event","enc":false,"unique":false,"cost":2,"res":"Y","cls":"Hero","tr":["THWART"],"traits":["저지"],"text":"<b>히어로 반응</b><i>(저지)</i>: 고스트 스파이더가 기본 기능을 사용한 후, 음모 하나에서 위협을 5만큼 제거합니다. (기본 기능 사용마다 최대 1장.)"},{"id":"27005","name":"피루엣과 펀치","en":"Pirouette and Punch","type":"event","enc":false,"unique":false,"cost":2,"res":"B","cls":"Hero","tr":["SKILL"],"traits":["기술"],"text":"<b>히어로 난입</b>: 조우 덱에서 카드가 공개될 때, 그 카드에 있는 강화 아이콘<i>([boost])</i>의 수보다 1 많은 피해를 빌런에게 입힙니다. 그 카드의 \"<b>공개될 때</b>\" 효과를 무효화합니다."},{"id":"27006","name":"거미줄 속박","en":"Web Binding","type":"event","enc":false,"unique":false,"cost":2,"res":"B","req":"B","cls":"Hero","tr":["SUPERPOWER"],"traits":["슈퍼파워"],"text":"요구 조건([mental]). <i>(이 카드의 비용을 지불할 때, 표시된 자원을 소모해야 합니다.)</i>\n<b>히어로 난입</b>: 적이 활성화하려 할 때, 그 활성화를 무효화합니다. 이렇게 하수인의 활성화가 무효화되었다면, 그 하수인에게 피해 4점을 입힙니다."},{"id":"27007","name":"조지 스테이시","en":"* George Stacy","type":"support","enc":false,"unique":true,"cost":1,"res":"Y","cls":"Hero","tr":["PERSONA"],"traits":["페르소나"],"text":"조지 스테이시에게 장착된 이벤트는 당신의 손에 있는 것처럼 플레이할 수 있습니다.\n<b>행동</b>: 조지 스테이시를 소진 → 당신의 손에서 이벤트 1장을 이 카드에 뒷면으로 장착(최대 3장까지)."},{"id":"27008","name":"멀티버스 티켓","en":"Ticket to the Multiverse","type":"upgrade","enc":false,"unique":false,"cost":3,"res":"GG","cls":"Hero","tr":["ITEM"],"traits":["도구"],"text":"<b>행동</b>: 멀티버스 티켓을 게임에서 제거 → 당신의 손을 버리고, 당신의 버린 더미를 당신의 덱에 섞어 넣고, 손 크기까지 카드를 뽑고, 당신이 조종하는 각 고스트 스파이더 카드를 준비."},{"id":"27009","name":"거미줄 팔찌","en":"Web-Bracelet","type":"upgrade","enc":false,"unique":false,"cost":2,"res":"R","cls":"Hero","tr":["ITEM","TECH"],"traits":["도구","과학"],"text":"<b>히어로 반응</b>: 당신이 이벤트의 \"<b>난입</b>\" 또는 \"<b>반응</b>\" 능력을 해결한 후, 거미줄 팔찌를 소진 → 카드 1장을 뽑음. (이벤트마다 최대 1회.)"},{"id":"27010","name":"실크","en":"* Silk","type":"ally","enc":false,"sub":"신디 문","unique":true,"hp":2,"atk":1,"atkStar":true,"thw":1,"thwStar":true,"cost":2,"res":"Y","cls":"Protection","tr":["WEB-WARRIOR"],"traits":["웹 워리어"],"text":"<b>반응</b>: 당신이 손에서 실크를 플레이한 후, 당신이 다른 [[웹 워리어]] 카드를 조종하고 있다면, 조우 덱에서 배반 카드 1장을 찾아 버립니다. <i>(섞습니다.)</i>"},{"id":"27011","name":"스파이더맨","en":"* Spider-Man","type":"ally","enc":false,"sub":"마일스 모랄레스","unique":true,"hp":3,"atk":2,"atkStar":true,"thw":1,"thwStar":true,"cost":4,"res":"B","cls":"Protection","tr":["WEB-WARRIOR"],"traits":["웹 워리어"],"text":"<b>반응</b>: 당신이 손에서 스파이더맨을 플레이한 후, 당신이 [[웹 워리어]] 카드를 3장 이상 조종하고 있다면, 적 하나를 기절시키고 혼란에 빠뜨립니다."},{"id":"27012","name":"스파이더 UK","en":"* Spider-UK","type":"ally","enc":false,"sub":"빌리 브래독","unique":true,"hp":5,"atk":2,"atkStar":true,"atkCons":2,"thw":1,"thwStar":true,"cost":3,"res":"R","cls":"Protection","tr":["WEB-WARRIOR"],"traits":["웹 워리어"],"text":"<b>난입</b>: 스파이더 UK가 공격을 방어할 때, 당신이 조종하는 [[웹 워리어]] 카드의 수만큼 공격하는 적에게 피해를 입힙니다."},{"id":"27013","name":"미끼 던지기","en":"Bait and Switch","type":"event","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Protection","tr":["THWART"],"traits":["저지"],"text":"<b>히어로 행동</b><i>(저지)</i>: 빌런이 당신을 공격합니다. 주요 음모에서 위협을 4만큼 제거합니다.","link":"15030"},{"id":"27014","name":"도약 공중제비","en":"Jump Flip","type":"event","enc":false,"unique":false,"cost":1,"res":"R","cls":"Protection","tr":["DEFENSE"],"traits":["방어"],"text":"<b>히어로 난입</b><i>(방어)</i>: 당신이 피해를 입으려 할 때, 그 피해에서 2점을 방지합니다. 당신이 [energy] 자원을 사용해 이 카드의 비용을 지불했다면, 주요 음모에서 위협을 2만큼 제거합니다."},{"id":"27015","name":"은혜 갚기","en":"Return the Favor","type":"event","enc":false,"unique":false,"cost":0,"res":"Y","cls":"Protection","tr":["ATTACK"],"traits":["공격"],"text":"<b>히어로 행동</b><i>(공격)</i>: 배반 카드를 버릴 때까지 조우 덱 맨 위에서 카드를 버립니다. 그 배반 카드를 공개 → 빌런에게 피해 5점을 입힘."},{"id":"27016","name":"나를 죽이지 못하는 것","en":"What Doesn't Kill Me","type":"event","enc":false,"unique":false,"cost":2,"res":"R","req":"R","cls":"Protection","tr":[],"traits":[],"text":"요구 조건([physical]) <i>(이 카드의 비용을 지불할 때, 나열된 자원을 소모해야 합니다.)</i>\n<b>히어로 행동</b>: 당신의 히어로가 입은 피해 2점을 치료 → 당신의 히어로를 준비."},{"id":"27017","name":"스파이더맨","en":"* Spider-Man","type":"ally","enc":false,"sub":"호비 브라운","unique":true,"hp":3,"atk":1,"atkStar":true,"thw":2,"thwStar":true,"thwCons":2,"cost":3,"res":"R","cls":"Basic","tr":["WEB-WARRIOR"],"traits":["웹 워리어"],"text":"당신이 [[웹 워리어]] 카드를 조종하고 있을 때만 플레이할 수 있습니다.\n<b>난입</b>: 스파이더맨이 플레이 영역을 떠날 때, 조우 덱 맨 위에서 카드 3장을 버립니다. 이렇게 버려진 강화 아이콘<i>([boost])</i>의 수만큼 빌런에게 피해를 입힙니다."},{"id":"27018","name":"스파이더버스 횡단","en":"Across the Spider-Verse","type":"event","enc":false,"unique":false,"cost":2,"res":"G","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.\n<b>히어로 행동</b>: 당신이 조종하는 [[웹 워리어]] 카드 1장을 소진 → 당신의 버린 더미에서 [[웹 워리어]] 동료 1장을 찾아 플레이 영역에 내려놓은 다음, 플레이어 하나를 선택. 그 플레이어는 아무 유형의 자원을 3개 소모해 이 능력을 반복해도 됨."},{"id":"27019","name":"풋사랑","en":"Young Love","type":"event","enc":false,"unique":false,"cost":1,"res":"G","cls":"Basic","tr":[],"teamUp":["Gwen Stacy","Miles Morales"],"maxDeck":1,"traits":[],"text":"협력(그웬 스테이시와 마일스 모랄레스). 덱마다 최대 1장.\n<b>일상 행동</b>: 그웬 스테이시와 마일스 모랄레스가 입은 피해를 각각 3점씩 치료합니다."},{"id":"27020","name":"에너지","en":"Energy","type":"resource","enc":false,"unique":false,"res":"YY","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01088"},{"id":"27021","name":"천재","en":"Genius","type":"resource","enc":false,"unique":false,"res":"BB","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01089"},{"id":"27022","name":"힘","en":"Strength","type":"resource","enc":false,"unique":false,"res":"RR","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01090"},{"id":"27023","name":"생명과 운명의 거미줄","en":"* Web of Life and Destiny","type":"support","enc":false,"unique":true,"cost":3,"res":"Y","cls":"Basic","tr":["LOCATION","WEB-WARRIOR"],"traits":["장소","웹 워리어"],"text":"당신의 아이덴티티가 [[웹 워리어]] 특성을 가지고 있다면 이 카드의 자원 비용을 무시합니다.\n<b>반응</b>: [[웹 워리어]] 동료가 플레이 영역을 떠난 후, 플레이어 하나를 선택 → 그 플레이어는 카드 1장을 뽑음."},{"id":"27024","name":"플랜 B","en":"Plan B","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"R","cls":"Basic","tr":["TACTIC"],"maxPer":1,"traits":["전술"],"text":"이 카드를 플레이하면, 조종할 플레이어를 정합니다. 플레이어마다 최대 1장.\n<b>히어로 행동</b>: 플랜 B를 소진하고 당신의 손에서 무작위 카드 1장을 버림 → 적 하나에게 피해 2점을 입힘."},{"id":"27025","name":"걱정하는 아버지","en":"Worried Father","type":"obligation","enc":true,"set":"Ghost-Spider","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b>그웬 스테이시 플레이어에게 이 카드를 줍니다.</b>\n당신의 덱, 손, 버린 더미, 플레이 영역에서 조지 스테이시를 찾아 이 카드에 뒷면으로 장착합니다.\n<b>일상 행동</b>: 그웬 스테이시를 소진하고 이 의무 카드를 게임에서 제거 → 조지 스테이시를 당신의 손에 더함."},{"id":"27026","name":"재생 연구","en":"Regenerative Research","type":"side","enc":true,"set":"Ghost-Spider Nemesis","unique":false,"boost":3,"start":5,"tr":[],"traits":[],"text":"<b>강제 난입</b>: 빌런 페이즈가 시작될 때, 각 적이 입은 피해 1점을 치료합니다."},{"id":"27027","name":"리저드","en":"* The Lizard","type":"minion","enc":true,"set":"Ghost-Spider Nemesis","unique":true,"hp":5,"atk":3,"sch":1,"boost":2,"tr":["BRUTE","CREATURE"],"nemesis":true,"traits":["야만","괴수"],"text":"<b>강제 난입</b>: 빌런 페이즈가 시작될 때, 리저드가 입은 피해 1점을 치료합니다.\n<i>(고스트 스파이더의 숙적 하수인.)</i>"},{"id":"27028","name":"실험용 주사","en":"Experimental Injection","type":"attachment","enc":true,"set":"Ghost-Spider Nemesis","unique":false,"tr":[],"traits":[],"text":"남은 생명력이 가장 많은 하수인에게 장착합니다. 그럴 수 없다면, 이 카드는 쇄도를 얻습니다.\n장착된 하수인은 [[괴수]] 특성을 얻고 생명력 +4를 받습니다."},{"id":"27029","name":"냉혈","en":"In Cold Blood","type":"treachery","enc":true,"set":"Ghost-Spider Nemesis","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 리저드가 당신을 공격합니다. 그 공격이 해결될 때까지 당신은 이벤트를 플레이할 수 없습니다. 이렇게 공격이 이루어지지 않았다면, 이 카드는 쇄도를 얻습니다."},{"id":"27030a","name":"스파이더맨","en":"* Spider-Man","type":"hero","enc":false,"unique":true,"hp":9,"atk":2,"thw":2,"def":2,"hs":5,"tr":["CHAMPION","WEB-WARRIOR"],"traits":["챔피언","웹 워리어"],"text":"<i>베놈 블래스트</i> - <b>특수</b>: 적 하나에게 피해 2점을 입힙니다. 그 적을 기절시킵니다.\n<i>거미 위장</i> - <b>특수</b>: 스파이더맨에게 강인함 상태 카드를 줍니다. 적 하나를 혼란에 빠뜨립니다."},{"id":"27030b","name":"마일스 모랄레스","en":"* Miles Morales","type":"alter","enc":false,"unique":true,"hp":9,"rec":4,"hs":6,"tr":["CIVILIAN"],"traits":["시민"],"text":"<b>반응</b>: 당신이 이 형태로 변신한 후, 당신의 버린 더미에서 스파이더맨 카드 1장을 당신의 덱에 섞어 넣습니다."},{"id":"27031","name":"거미 곡예","en":"Arachnobatics","type":"event","enc":false,"unique":false,"cost":1,"res":"B","cls":"Hero","tr":["ATTACK"],"traits":["공격"],"text":"<b>히어로 행동</b><i>(공격)</i>: 적 하나에게 피해 2점을 입힙니다. 그 적이 기절 상태 카드를 가지고 있다면, 그 적에게 피해 3점을 추가로 입힙니다. 그 적이 혼란 상태 카드를 가지고 있다면, 그 적에게 피해 3점을 추가로 입힙니다."},{"id":"27032","name":"이중생활","en":"Double Life","type":"event","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Hero","tr":[],"traits":[],"text":"라운드마다 최대 1장.\n<b>행동</b>: 당신의 형태를 변경합니다. 당신이 [physical] 자원을 사용해 이 카드의 비용을 지불했다면, 당신의 아이덴티티를 준비합니다."},{"id":"27033","name":"날아 들어오기","en":"Swing In","type":"event","enc":false,"unique":false,"cost":2,"res":"Y","cls":"Hero","tr":["THWART"],"traits":["저지"],"text":"<b>히어로 행동</b><i>(저지)</i>: 음모 하나에서 위협을 4만큼 제거합니다. 당신이 [mental] 자원을 사용해 이 카드의 비용을 지불했다면, 스파이더맨의 <i>\"거미 위장\"</i> 능력을 해결합니다."},{"id":"27034","name":"거미줄 발사","en":"Web-Shot","type":"event","enc":false,"unique":false,"cost":2,"res":"B","cls":"Hero","tr":["ATTACK"],"traits":["공격"],"text":"<b>히어로 행동</b><i>(공격)</i>: 적 하나에게 피해 4점을 입힙니다. 당신이 [energy] 자원을 사용해 이 카드의 비용을 지불했다면, 스파이더맨의 <i>\"베놈 블래스트\"</i> 능력을 해결합니다."},{"id":"27035","name":"갱키 리","en":"* Ganke Lee","type":"support","enc":false,"unique":true,"cost":2,"res":"G","cls":"Hero","tr":["PERSONA"],"traits":["페르소나"],"text":"<b>행동</b>: 갱키 리를 소진 → 카드 1장을 뽑음. 당신이 히어로 형태라면, 당신의 손에서 카드 1장을 선택해 버림."},{"id":"27036","name":"제퍼슨 데이비스","en":"* Jefferson Davis","type":"support","enc":false,"unique":true,"cost":2,"res":"R","cls":"Hero","tr":["PERSONA","S.H.I.E.L.D"],"traits":["페르소나","S.H.I.E.L.D"],"text":"<b>일상 행동</b>: 제퍼슨 데이비스를 소진 → 위협이 가장 적은 음모에서 위협을 1만큼 제거."},{"id":"27037","name":"내면의 힘","en":"Power Within","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Hero","tr":["SUPERPOWER"],"traits":["슈퍼파워"],"text":"<b>히어로 반응</b>: 당신의 히어로가 기본 기능을 사용한 후, 내면의 힘을 버림 → 스파이더맨의 <i>\"베놈 블래스트\"</i> 능력을 해결."},{"id":"27038","name":"방어 기제","en":"Defense Mechanism","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"B","cls":"Hero","tr":["SUPERPOWER"],"traits":["슈퍼파워"],"text":"<b>히어로 반응</b>: 당신의 히어로가 기본 기능을 사용한 후, 방어 기제를 버림 → 스파이더맨의 <i>\"거미 위장\"</i> 능력을 해결."},{"id":"27039","name":"웹슈터","en":"Web-Shooter","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"R","cls":"Hero","tr":["ITEM","TECH"],"uses":{"n":3,"kind":"web"},"traits":["도구","과학"],"text":"사용(웹 카운터 3). <i>(카운터를 3만큼 놓은 채로 플레이 영역에 들어옵니다. 카운터가 모두 사라지면 이 카드를 버립니다.)</i>\n<b>히어로 자원</b>: 웹슈터를 소진하고 이 카드에서 웹 카운터를 1만큼 제거 → [wild] 자원을 생성."},{"id":"27040","name":"모니카 창","en":"* Monica Chang","type":"ally","enc":false,"unique":true,"hp":2,"atk":1,"atkStar":true,"thw":1,"thwStar":true,"cost":3,"res":"B","cls":"Justice","tr":["S.H.I.E.L.D"],"traits":["S.H.I.E.L.D"],"text":"<b>반응</b>: 모니카 창이 플레이 영역에 들어온 후, 당신의 덱, 손, 버린 더미에서 감시팀 지원 카드 1장을 찾아 플레이 영역에 내려놓습니다. 당신이 조종하는 각 감시팀에 염탐 카운터를 1만큼 놓습니다."},{"id":"27041","name":"스파이더우먼","en":"* Spider-Woman","type":"ally","enc":false,"sub":"제시카 드류","unique":true,"hp":3,"atk":2,"atkStar":true,"atkCons":2,"thw":1,"thwStar":true,"cost":3,"res":"B","cls":"Justice","tr":["S.H.I.E.L.D","WEB-WARRIOR"],"traits":["S.H.I.E.L.D","웹 워리어"],"text":"플레이 영역에 있는 혼란 상태인 적마다 스파이더우먼을 플레이하는 비용이 1만큼 감소합니다."},{"id":"27042","name":"본국 개입","en":"Homeland Intervention","type":"event","enc":false,"unique":false,"cost":0,"res":"Y","cls":"Justice","tr":["S.H.I.E.L.D","TACTIC"],"traits":["S.H.I.E.L.D","전술"],"text":"<b>행동</b>: 당신이 조종하는 [[S.H.I.E.L.D.]] 카드를 3장까지 소진하고 음모 하나를 선택 → 이렇게 소진한 카드마다 그 음모에서 위협을 2만큼 제거."},{"id":"27043","name":"글로벌 물류","en":"Global Logistics","type":"event","enc":false,"unique":false,"cost":0,"res":"R","cls":"Justice","tr":["S.H.I.E.L.D","TACTIC"],"traits":["S.H.I.E.L.D","전술"],"text":"<b>행동</b>: 당신이 조종하는 [[S.H.I.E.L.D.]] 카드 1장을 소진 → 플레이어 덱 하나 또는 조우 덱의 맨 위 카드 4장을 봄. 그중 원하는 수만큼 버리고, 나머지는 원하는 순서대로 그 덱의 맨 위 및/또는 맨 아래에 놓음."},{"id":"27044","name":"현장 요원","en":"Field Agent","type":"support","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Justice","tr":["PERSONA","S.H.I.E.L.D"],"uses":{"n":3,"kind":"backup"},"traits":["페르소나","S.H.I.E.L.D"],"text":"사용(증원 카운터 3).\n<b>히어로 난입</b>: [[S.H.I.E.L.D.]] 동료가 부수적 피해를 입으려 할 때, 현장 요원을 소진하고 이 카드에서 증원 카운터를 1만큼 제거 → 그 피해에서 1점을 방지."},{"id":"27045","name":"감시팀","en":"Surveillance Team","type":"support","enc":false,"unique":false,"cost":2,"res":"B","cls":"Justice","tr":["S.H.I.E.L.D"],"uses":{"n":3,"kind":"snoop"},"traits":["S.H.I.E.L.D"],"text":"사용(정찰 카운터 3). <i>(카운터를 3만큼 놓은 채로 플레이 영역에 들어옵니다. 카운터가 모두 사라지면 이 카드를 버립니다)</i>\n<b>행동</b>: 감시팀을 소진하고 이 카드에서 감시 카운터를 1만큼 제거 → 음모 하나에서 위협을 1만큼 제거.","link":"01064"},{"id":"27046","name":"에이전트 13","en":"* Agent 13","type":"ally","enc":false,"sub":"샤론 카터","unique":true,"hp":4,"atk":1,"atkStar":true,"thw":2,"thwStar":true,"cost":4,"res":"R","cls":"Basic","tr":["S.H.I.E.L.D","SPY"],"traits":["S.H.I.E.L.D","첩보원"],"text":"[star] <b>반응</b>: 에이전트 13이 공격하거나 저지한 후, [[S.H.I.E.L.D.]] 지원 카드 1장을 선택 → 그 지원 카드를 준비.","star":true},{"id":"27047","name":"덤덤 듀건","en":"* Dum Dum Dugan","type":"ally","enc":false,"unique":true,"hp":5,"atk":3,"atkStar":true,"atkCons":2,"thw":3,"thwStar":true,"thwCons":3,"cost":5,"res":"R","cls":"Basic","tr":["S.H.I.E.L.D"],"traits":["S.H.I.E.L.D"],"text":"<b>난입</b>: 당신이 덤덤 듀건의 기본 기능 중 하나를 사용할 때, 당신이 조종하는 [[S.H.I.E.L.D.]] 카드를 3장까지 소진합니다. 이렇게 소진한 카드마다, 덤덤 듀건은 이번 사용에 한해 그 기능에 +1을 받습니다."},{"id":"27048","name":"고스트 스파이더","en":"* Ghost-Spider","type":"ally","enc":false,"sub":"그웬 스테이시","unique":true,"hp":3,"atk":2,"atkStar":true,"thw":1,"thwStar":true,"cost":3,"res":"G","cls":"Basic","tr":["WEB-WARRIOR"],"traits":["웹 워리어"],"text":"당신이 [[웹 워리어]] 카드를 조종하고 있을 때만 플레이할 수 있습니다.\n<b>난입</b>: 고스트 스파이더가 플레이 영역을 떠날 때, 당신의 덱에서 아이덴티티 전용 이벤트 1장을 찾아 당신의 손에 더합니다. <i>(섞습니다.)</i>"},{"id":"27049","name":"스파이더맨","en":"* Spider-Man","type":"ally","enc":false,"sub":"피터 파커","unique":true,"hp":3,"atk":2,"atkStar":true,"thw":2,"thwStar":true,"cost":3,"res":"B","req":"YBR","cls":"Basic","tr":["WEB-WARRIOR"],"traits":["웹 워리어"],"text":"요구 조건([energy] [mental] [physical]). <i>(이 카드의 비용을 지불할 때, 나열된 자원을 소모해야 합니다.)</i>\n<b>반응</b>: 스파이더맨이 공격하거나 저지한 후, 다른 [[웹 워리어]] 캐릭터 하나를 선택 → 그 캐릭터를 준비."},{"id":"27050","name":"풋사랑","en":"Young Love","type":"event","enc":false,"unique":false,"cost":1,"res":"G","cls":"Basic","tr":[],"teamUp":["Gwen Stacy","Miles Morales"],"maxDeck":1,"traits":[],"text":"협력(그웬 스테이시와 마일스 모랄레스). 덱마다 최대 1장.\n<b>일상 행동</b>: 그웬 스테이시와 마일스 모랄레스가 입은 피해를 각각 3점씩 치료합니다.","link":"27019"},{"id":"27051","name":"에너지","en":"Energy","type":"resource","enc":false,"unique":false,"res":"YY","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01088"},{"id":"27052","name":"천재","en":"Genius","type":"resource","enc":false,"unique":false,"res":"BB","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01089"},{"id":"27053","name":"힘","en":"Strength","type":"resource","enc":false,"unique":false,"res":"RR","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01090"},{"id":"27054","name":"정부 연락관","en":"Government Liaison","type":"support","enc":false,"unique":false,"cost":2,"res":"B","cls":"Basic","tr":["PERSONA","S.H.I.E.L.D"],"traits":["페르소나","S.H.I.E.L.D"],"text":"<b>히어로 행동</b>: 정부 연락관을 소진 → 당신의 손에서 [[S.H.I.E.L.D.]] 카드 1장을 자원 비용을 1만큼 줄여 플레이."},{"id":"27055","name":"스카이 디스트로이어","en":"* Sky-Destroyer","type":"support","enc":false,"unique":true,"cost":3,"res":"Y","cls":"Basic","tr":["S.H.I.E.L.D","VEHICLE"],"traits":["S.H.I.E.L.D","탈것"],"text":"<b>반응</b>: 당신이 [[S.H.I.E.L.D.]] 카드를 플레이한 후, 스카이 디스트로이어를 소진 → 적 하나에게 피해 2점을 입힘."},{"id":"27056","name":"비밀 유지","en":"Keeping Secrets","type":"obligation","enc":true,"set":"Spider-Man - Miles Morales","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b>마일스 모랄레스 플레이어에게 이 카드를 줍니다.</b>\n당신은 일상 형태로 카드를 뒤집어도 됩니다. 다음 중 하나를 선택합니다.\n• 마일스 모랄레스를 소진 → 비밀 유지를 게임에서 제거.\n• 플레이 영역에서 갱키 리와 제퍼슨 데이비스를 버립니다. 이렇게 버려진 카드가 없다면, 이 카드는 쇄도를 얻습니다. 이 의무 카드를 버립니다."},{"id":"27057","name":"사냥감 추적","en":"Tracking Prey","type":"side","enc":true,"set":"Spider-Man - Morales Nemesis","unique":false,"boost":3,"start":4,"accel":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 당신이 일상 형태라면, 이 카드에 가속 토큰을 1개 놓습니다."},{"id":"27058","name":"프라울러","en":"* Prowler","type":"minion","enc":true,"set":"Spider-Man - Morales Nemesis","unique":true,"hp":5,"atk":2,"sch":1,"boost":2,"tr":["CRIMINAL"],"stalwart":1,"nemesis":true,"traits":["범죄자"],"text":"견고.\n<b>공개될 때</b>: 당신이 일상 형태라면, 프라울러에게 강인함 상태 카드를 줍니다.\n<i>(스파이더맨의 숙적 하수인)</i>"},{"id":"27059","name":"면도날 발톱","en":"Razor Claws","type":"attachment","enc":true,"set":"Spider-Man - Morales Nemesis","unique":false,"boost":2,"plus":{"atk":2},"tr":["WEAPON"],"traits":["무기"],"text":"인쇄된 생명력이 가장 높은 하수인에게 장착합니다. 그럴 수 없다면, 이 카드는 쇄도를 얻습니다.\n[star] 장착된 하수인의 공격은 관통을 얻습니다.","star":true},{"id":"27060","name":"난도질","en":"Slice and Dice","type":"treachery","enc":true,"set":"Spider-Man - Morales Nemesis","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 프라울러가 남은 생명력이 가장 적은 플레이어를 공격합니다 <i>(그 플레이어가 일상 형태여도 공격합니다)</i>. 그 공격이 캐릭터를 격파했거나 이렇게 공격이 이루어지지 않았다면, 이 카드는 쇄도를 얻습니다."},{"id":"27061","name":"샌드맨","en":"* Sandman","type":"villain","enc":true,"set":"Sandman","unique":true,"hp":16,"hpStar":true,"atk":2,"sch":1,"stage":1,"tr":["CRIMINAL"],"traits":["범죄자"],"text":"<i>모래 폭발</i> — [star] <b>강제 난입</b>: 샌드맨이 당신을 공격할 때, 그 공격은 간접 피해를 입힙니다. 당신의 아이덴티티가 그 공격으로 피해를 입었다면, 도시의 거리에 있는 \"<i>솟구치는 모래</i>\" 능력을 해결합니다.","star":true},{"id":"27062","name":"샌드맨","en":"* Sandman","type":"villain","enc":true,"set":"Sandman","unique":true,"hp":18,"hpStar":true,"atk":3,"sch":1,"stage":2,"tr":["CRIMINAL"],"traits":["범죄자"],"text":"<b>공개될 때</b>: 도시의 거리에 있는 \"<i>솟구치는 모래</i>\" 능력을 해결합니다.\n<i>모래 폭발</i> — [star] <b>강제 난입</b>: 샌드맨이 당신을 공격할 때, 그 공격은 간접 피해를 입힙니다. 당신의 아이덴티티가 그 공격으로 피해를 입었다면, 도시의 거리에 있는 \"<i>솟구치는 모래</i>\" 능력을 해결합니다.","star":true},{"id":"27063","name":"샌드맨","en":"* Sandman","type":"villain","enc":true,"set":"Sandman","unique":true,"hp":19,"hpStar":true,"atk":3,"sch":1,"stage":3,"tr":["CRIMINAL"],"traits":["범죄자"],"text":"<b>공개될 때</b>: 도시의 거리에 모래 카운터를 1만큼 놓습니다. 그 카드의 \"<i>솟구치는 모래</i>\" 능력을 해결합니다.\n<i>모래 파도</i> — [star] <b>강제 난입</b>: 샌드맨이 당신을 공격할 때, 그 공격은 압살을 얻습니다. 당신의 아이덴티티가 그 공격으로 피해를 입었다면, 도시의 거리에 있는 \"<i>솟구치는 모래</i>\" 능력을 해결합니다.","star":true},{"id":"27064a","name":"불운한 행인들","en":"Hapless Pedestrians","type":"main","enc":true,"set":"Sandman","unique":false,"stage":1,"tr":[],"traits":[],"text":"<b>구성</b>: 샌드맨 (I)과 샌드맨 (II). <i>(전문가 모드에서는 대신 샌드맨 (II)와 샌드맨 (III).)</i> 샌드맨, 혼돈의 도시, 일반 조우 세트. 모듈식 조우 세트 1개 <i>(지상으로)</i>.\n<b>사전 준비</b>: 조우 덱에서 도시의 거리 환경 카드를 찾아 플레이 영역에 내려놓습니다. 그 카드에 모래 카운터를 4만큼 놓습니다."},{"id":"27064b","name":"불운한 행인들","en":"Hapless Pedestrians","type":"main","enc":true,"set":"Sandman","unique":false,"start":2,"startStar":true,"target":9,"targetStar":true,"esc":1,"escStar":true,"stage":1,"tr":[],"traits":[],"text":"<b>강제 반응</b>: 이 음모에 가속 토큰이 놓인 후, 시작 플레이어에게 간접 피해 3점을 입힙니다.\n<b>이 스테이지가 완료되면, 플레이어들은 게임에서 패배합니다.</b>"},{"id":"27065","name":"도시의 거리","en":"City Streets","type":"environment","enc":true,"set":"Sandman","unique":false,"tr":["LOCATION"],"traits":["장소"],"text":"<i>솟구치는 모래</i> — <b>특수</b>: 이 카드에 모래 카운터를 1만큼 놓습니다. 이 카드에 놓인 모래 카운터의 수만큼 조우 덱 맨 위에서 카드를 버립니다.\n<b>히어로 행동</b>: 당신이 조종하는 캐릭터 하나를 소진 → 그 캐릭터의 공격만큼 이 카드에서 모래 카운터를 제거. (플레이어마다 라운드마다 1회 제한.)"},{"id":"27066","name":"모래 형태","en":"Sand Form","type":"attachment","enc":true,"set":"Sandman","unique":false,"tr":["CONDITION"],"traits":["상태"],"text":"샌드맨에게 장착합니다.\n<b>강제 난입</b>: 당신이 샌드맨에게 피해를 입히려 할 때, 대신 모래 형태를 버림 → 도시의 거리에 있는 \"<i>솟구치는 모래</i>\" 능력을 해결.\n<hr />\n[star] <b>강화</b>: 이 카드를 공개합니다.","star":true,"boostStar":true},{"id":"27067","name":"모래 분신","en":"Sand Clone","type":"minion","enc":true,"set":"Sandman","unique":false,"hp":3,"atk":0,"sch":1,"tr":[],"traits":[],"text":"X는 도시의 거리에 놓인 모래 카운터의 수와 같습니다.\n<b>격파될 때</b>: 도시의 거리에 있는 \"<i>솟구치는 모래</i>\" 능력을 해결합니다."},{"id":"27068","name":"흙 함정","en":"Dirt Trap","type":"side","enc":true,"set":"Sandman","unique":false,"boost":3,"start":1,"tr":[],"crisis":1,"traits":[],"text":"<b>격파될 때</b>: 도시의 거리에 있는 \"<i>솟구치는 모래</i>\" 능력을 해결합니다. 그 능력을 한 번 더 해결합니다."},{"id":"27069","name":"밀려오는 모래","en":"Tidal Sands","type":"side","enc":true,"set":"Sandman","unique":false,"boost":2,"start":2,"hazard":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 이 카드에 위협을 X만큼 추가로 놓습니다. X는 도시의 거리에 놓인 모래 카운터의 수와 같습니다."},{"id":"27070","name":"모래 사태","en":"Sandslide","type":"treachery","enc":true,"set":"Sandman","unique":false,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 도시의 거리에 모래 카운터를 2만큼 놓은 다음, 그 카드의 \"<i>솟구치는 모래</i>\" 능력을 해결합니다. 이렇게 샌드맨 카드가 1장 이상 버려졌다면, 당신은 기절합니다.\n<hr />\n[star] <b>강화</b>: 이 카드의 \"<b>공개될 때</b>\" 능력을 해결합니다.","star":true,"boostStar":true},{"id":"27071","name":"모래 폭풍","en":"Sand Storm","type":"treachery","enc":true,"set":"Sandman","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 플레이어들에게 간접 피해 X점을 입힙니다 <i>(당신이 원하는 대로 나눕니다)</i>. X는 도시의 거리에 놓인 모래 카운터의 수와 같습니다. 도시의 거리에 모래 카운터가 없다면, 그 카드에 모래 카운터를 3만큼 놓고 이 카드를 조우 덱에 섞어 넣습니다."},{"id":"27072","name":"모래 강타","en":"Sand Smash","type":"treachery","enc":true,"set":"Sandman","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때 (일상)</b>: 도시의 거리에 있는 \"<i>솟구치는 모래</i>\" 능력을 해결합니다. 이 카드는 쇄도를 얻습니다.\n<b>공개될 때 (히어로)</b>: 샌드맨이 공격 +1을 받은 채 당신을 공격합니다."},{"id":"27073","name":"베놈","en":"* Venom","type":"villain","enc":true,"set":"Venom","unique":true,"hp":17,"hpStar":true,"atk":2,"sch":1,"stage":1,"tr":["SYMBIOTE"],"toughness":1,"traits":["심비오트"],"text":"강인. (이 캐릭터는 강인함 상태 카드를 가진 채 플레이 영역에 들어옵니다.)\n<i>복수</i> — <b>강제 반응</b>: 당신 또는 당신이 조종하는 동료가 베놈을 공격하여 피해를 입힌 후, 당신의 아이덴티티에 강화 카드 1장을 뒷면으로 놓습니다."},{"id":"27074","name":"베놈","en":"* Venom","type":"villain","enc":true,"set":"Venom","unique":true,"hp":18,"hpStar":true,"atk":2,"sch":2,"stage":2,"tr":["SYMBIOTE"],"toughness":1,"steady":1,"traits":["심비오트"],"text":"강인. 의연.\n<b>공개될 때</b>: 조우 덱과 버린 조우 더미에서 필사적으로 부가 음모를 찾아 플레이 영역에 내려놓습니다. <i>(섞습니다.)</i>\n<i>복수</i> — <b>강제 반응</b>: 당신 또는 당신이 조종하는 동료가 베놈을 공격하여 피해를 입힌 후, 당신의 아이덴티티에 강화 카드 1장을 뒷면으로 놓습니다."},{"id":"27075","name":"베놈","en":"* Venom","type":"villain","enc":true,"set":"Venom","unique":true,"hp":20,"hpStar":true,"atk":3,"sch":2,"stage":3,"retaliate":1,"tr":["SYMBIOTE"],"toughness":1,"steady":1,"traits":["심비오트"],"text":"반격 1. 의연. 강인.\n<b>공개될 때</b>: 각 아이덴티티에 강화 카드 2장을 뒷면으로 놓습니다.\n<i>응징</i> — <b>강제 반응</b>: 당신 또는 당신이 조종하는 동료가 베놈을 공격하여 피해를 입힌 후, 당신의 아이덴티티에 강화 카드 1장을 뒷면으로 놓습니다(이번 차례의 첫 번째 공격이라면 대신 강화 카드 2장을 뒷면으로)."},{"id":"27076a","name":"\"우리를 내버려 둬!\"","en":"\"Leave Us Alone!\"","type":"main","enc":true,"set":"Venom","unique":false,"stage":1,"tr":[],"traits":[],"text":"<b>구성</b>: 베놈 (I)과 베놈 (II). <i>(전문가 모드에서는 대신 베놈 (II)와 베놈 (III).)</i> 베놈, 공생의 힘, 일반 조우 세트. 모듈식 조우 세트 1개 <i>(지상으로.)</i>\n<b>사전 준비</b>: 종탑 환경 카드를 [[고요]] 면이 앞면이 되도록 플레이 영역에 내려놓습니다."},{"id":"27076b","name":"\"우리를 내버려 둬!\"","en":"\"Leave Us Alone!\"","type":"main","enc":true,"set":"Venom","unique":false,"start":2,"startStar":true,"target":10,"targetStar":true,"esc":1,"escStar":true,"stage":1,"tr":[],"traits":[],"text":"<b>강제 난입</b>: 베놈이 당신을 상대로 활성화할 때, 당신의 아이덴티티에 있는 뒷면 강화 카드를 모두 베놈에게 옮깁니다.\n<b>이 스테이지가 완료되면, 플레이어들은 게임에서 패배합니다.</b>"},{"id":"27077a","name":"종탑","en":"Bell Tower","type":"environment","enc":true,"set":"Venom","unique":false,"tr":["LOCATION","QUIET"],"traits":["장소","고요"],"text":"이 카드에 종소리 카운터가 3[per_hero] 이상 있다면, 이 카드를 뒤집습니다.\n<b>난입: </b> 공격으로 베놈에게 피해가 주어지려 할 때, 대신 그만큼의 종소리 카운터를 이 카드에 놓을 수 있습니다."},{"id":"27077b","name":"종탑","en":"Bell Tower","type":"environment","enc":true,"set":"Venom","unique":false,"tr":["LOCATION","RINGING"],"traits":["장소","울림"],"text":"베놈이 입는 모든 피해를 1만큼 증가시킵니다.\n이 카드에 종소리 카운터가 없다면, 이 카드를 뒤집습니다.\n<b>강제 난입</b>: 베놈의 공격이 아이덴티티에게 피해를 입히려 할 때, 그만큼의 종소리 카운터를 이 카드에서 제거합니다. 이렇게 제거된 종소리 카운터마다, 그 피해에서 1점을 방지합니다."},{"id":"27078","name":"\"이제 화났다!\"","en":"\"Now We're Angry!\"","type":"attachment","enc":true,"set":"Venom","unique":false,"plus":{"atk":1},"tr":["CONDITION"],"uses":{"n":2,"kind":"rage"},"traits":["상태"],"text":"베놈에게 장착합니다.\n사용(분노 카운터 2).\n[star] 베놈의 공격은 압살을 얻습니다.\n<b>강제 반응</b>: 베놈이 공격으로 피해를 입은 후, 이 카드에서 분노 카운터를 1만큼 제거합니다.\n<hr />\n[star] <b>강화</b>: 이 카드를 공개합니다.","star":true,"boostStar":true},{"id":"27079","name":"종탑 사수","en":"Guard the Bell Tower","type":"side","enc":true,"set":"Venom","unique":false,"boost":2,"start":3,"tr":[],"traits":[],"text":"종탑의 인쇄된 문구 상자는 비어 있는 것으로 간주합니다 <i>([[특성]] 제외)</i>.\n<b>공개될 때</b>: 종탑에서 종소리 카운터를 모두 제거하고 종탑을 [[고요]] 면으로 뒤집습니다."},{"id":"27080","name":"분풀이","en":"Lashing Out","type":"side","enc":true,"set":"Venom","unique":false,"boost":1,"start":9,"accel":1,"tr":[],"traits":[],"text":"<b>반응</b>: 베놈이 공격으로 피해를 입은 후, 이 카드에서 같은 양의 위협을 제거합니다.\n<hr />\n[star] <b>강화</b>: 이 활성화가 공격이라면, 간접 피해 2점을 입습니다.","star":true,"boostStar":true},{"id":"27081","name":"필사적으로","en":"Tooth and Nail","type":"side","enc":true,"set":"Venom","unique":false,"boost":2,"start":8,"hazard":1,"tr":[],"traits":[],"text":"<b>반응</b>: 베놈이 공격으로 피해를 입은 후, 이 카드에서 같은 양의 위협을 제거합니다.\n<hr />\n[star] <b>강화</b>: 이 활성화가 공격이라면, 그 공격은 관통을 얻습니다.","star":true,"boostStar":true},{"id":"27082","name":"신랄한 응수","en":"Biting Retort","type":"treachery","enc":true,"set":"Venom","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 베놈이 당신을 상대로 활성화합니다. 그 활성화 동안 앞면으로 뒤집힌 각 강화 카드는 강화 아이콘 [boost]를 1개 더 얻습니다.\n<hr />\n[star] <b>강화</b>: 종탑에서 종소리 카운터를 1만큼 제거합니다.","star":true,"boostStar":true},{"id":"27083","name":"누구를 위하여 종은 울리나","en":"For Whom the Bell Tolls","type":"treachery","enc":true,"set":"Venom","unique":false,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 종탑에서 종소리 카운터를 2만큼 제거합니다. 종탑이 [[고요]] 면이라면, 피해 1점을 입습니다. [[울림]] 면이라면, 주요 음모에서 위협을 1만큼 제거합니다.\n<hr />\n[star] <b>강화</b>: 이 카드의 \"<b>공개될 때</b>\" 능력을 해결합니다.","star":true,"boostStar":true},{"id":"27084","name":"미스테리오","en":"* Mysterio","type":"villain","enc":true,"set":"Mysterio","unique":true,"hp":15,"hpStar":true,"atk":1,"sch":2,"stage":1,"tr":["CRIMINAL"],"traits":["범죄자"],"text":"<i>공포의 씨앗</i> — [star] <b>강제 반응</b>: 미스테리오의 활성화 동안 당신이 강화 카드를 해결한 후, 그 카드가 [[환영]] 특성을 가지고 있다면 그 카드를 당신의 버린 더미에 놓습니다.","star":true},{"id":"27085","name":"미스테리오","en":"* Mysterio","type":"villain","enc":true,"set":"Mysterio","unique":true,"hp":17,"hpStar":true,"atk":2,"sch":2,"stage":2,"tr":["CRIMINAL"],"traits":["범죄자"],"text":"<b>공개될 때</b>: 플레이어 순서대로, 조우 덱 맨 위 카드를 각 플레이어의 덱에 섞어 넣습니다.\n<i>스며드는 공포</i> — [star] <b>강제 반응</b>: 미스테리오의 활성화 동안 당신이 강화 카드를 해결한 후, 그 카드가 [[환영]] 특성을 가지고 있다면 그 카드를 당신의 덱 맨 아래에 놓습니다.","star":true},{"id":"27086","name":"미스테리오","en":"* Mysterio","type":"villain","enc":true,"set":"Mysterio","unique":true,"hp":16,"hpStar":true,"atk":2,"sch":2,"stage":3,"tr":["CRIMINAL"],"traits":["범죄자"],"text":"<b>공개될 때</b>: 각 플레이어의 덱 맨 위에서 카드 5장을 버립니다.\n<i>공포의 속박</i> — [star] <b>강제 반응</b>: 미스테리오의 활성화 동안 당신이 강화 카드를 해결한 후, 그 카드가 [[환영]] 특성을 가지고 있다면 그 카드를 당신의 덱 맨 위에 놓습니다.","star":true},{"id":"27087a","name":"거울 미로","en":"Maze of Mirrors","type":"main","enc":true,"set":"Mysterio","unique":false,"stage":1,"tr":[],"traits":[],"text":"<b>구성</b>: 미스테리오 (I), 미스테리오 (II). <i>(전문가 모드에서는 대신 미스테리오 (II), 미스테리오 (III).)</i> 미스테리오, 개인적인 악몽, 일반 조우 세트. 모듈식 조우 세트 하나 <i>(편집증의 속삭임)</i>.\n<b>사전 준비</b>: 각 플레이어와 교전 중인 채로 변하는 환영 하수인 하나를 플레이 영역에 내려놓습니다. <i>(덱을 섞습니다.)</i>"},{"id":"27087b","name":"거울 미로","en":"Maze of Mirrors","type":"main","enc":true,"set":"Mysterio","unique":false,"start":2,"startStar":true,"target":8,"targetStar":true,"esc":1,"escStar":true,"stage":1,"tr":[],"traits":[],"text":"<b>강제 난입</b>: 당신이 당신의 덱에서 조우 카드를 뽑거나 버리려 할 때, 그 카드를 당신에게 뒷면 조우 카드로 나누어 줌 → 카드 1장을 뽑음."},{"id":"27088a","name":"현실의 경계","en":"Edge of Reality","type":"main","enc":true,"set":"Mysterio","unique":false,"stage":2,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 플레이어 순서대로, 조우 덱 맨 위 카드 2장을 각 플레이어의 덱에 섞어 넣습니다."},{"id":"27088b","name":"현실의 경계","en":"Edge of Reality","type":"main","enc":true,"set":"Mysterio","unique":false,"start":3,"startStar":true,"target":9,"targetStar":true,"esc":1,"escStar":true,"stage":2,"tr":[],"traits":[],"text":"<b>강제 난입</b>: 당신이 당신의 덱에서 조우 카드를 뽑거나 버리려 할 때, 그 카드를 당신에게 뒷면 조우 카드로 나누어 줌 → 카드 1장을 뽑음.\n<b>이 스테이지가 완료되면, 플레이어들은 게임에서 패배합니다.</b>"},{"id":"27089","name":"거대한 환각","en":"Humongous Hallucination","type":"attachment","enc":true,"set":"Mysterio","unique":false,"boost":3,"plus":{"atk":3},"tr":["ILLUSION"],"traits":["환영"],"text":"미스테리오에게 장착합니다.\n<b>히어로 행동: </b> 아무 유형의 자원 1개를 소모하고 조우 덱 맨 위 카드 2장을 당신의 덱에 섞어 넣음 → 이 카드를 버림."},{"id":"27090","name":"완벽한 신기루","en":"Masterful Mirage","type":"attachment","enc":true,"set":"Mysterio","unique":false,"boost":1,"plus":{"sch":1},"tr":["ILLUSION"],"traits":["환영"],"text":"미스테리오에게 장착합니다.\n<b>강제 난입</b> 당신이 미스테리오에게 피해를 입히려 할 때, 대신 당신의 덱 맨 위에서 카드 4장을 버립니다. 이 카드를 버립니다.\n<hr />\n[star] <b>강화</b>: 이번 활성화에 미스테리오에게 강화 카드 1장을 추가로 줍니다.","star":true,"boostStar":true},{"id":"27091","name":"변하는 환영","en":"Shifting Apparition","type":"minion","enc":true,"set":"Mysterio","unique":false,"hp":1,"atk":1,"sch":1,"boost":1,"tr":["ILLUSION"],"guard":1,"traits":["환영"],"text":"경호. <i>(이 하수인이 당신과 교전 중인 한, 당신은 빌런을 공격할 수 없습니다.)</i>\n<b>격파될 때</b>: 이 하수인이 초과 피해로 격파되었다면, 격파한 플레이어는 조우 덱 맨 위 카드를 자신의 덱에 섞어 넣습니다."},{"id":"27092","name":"데자뷔","en":"Déjà Vu","type":"treachery","enc":true,"set":"Mysterio","unique":false,"tr":[],"peril":1,"traits":[],"text":"고립. <i>(당신이 이 카드를 해결하는 동안, 다른 플레이어는 당신을 도울 수 없습니다.)</i>\n<b>공개될 때</b>: 피해 1점을 입거나 주요 음모에 위협을 1만큼 놓는 것 중 하나를 선택합니다. 데자뷔를 아무 플레이어의 덱에 섞어 넣습니다.\n<hr />\n[star] <b>강화</b>: 이 카드를 공개합니다.","star":true,"boostStar":true},{"id":"27093","name":"공포 조장자","en":"Fearmonger","type":"treachery","enc":true,"set":"Mysterio","unique":false,"surge":1,"tr":[],"traits":[],"text":"쇄도.\n<b>공개될 때</b>: 당신의 손을 모두 버립니다. 당신의 손 크기까지 카드를 뽑습니다.\n<hr />\n[star] <b>강화</b>: [mental][mental] 자원을 소모하거나 이 카드를 당신에게 뒷면 조우 카드로 나누어 주는 것 중 하나를 선택합니다.","star":true,"boostStar":true},{"id":"27094","name":"닥터 옥토퍼스","en":"* Doctor Octopus","type":"villain","enc":true,"set":"Sinister Six","unique":true,"hp":8,"atk":2,"sch":2,"stage":1,"tr":["ACTIVATION ORDER 1"],"traits":["활성화 순서 1"],"text":"[star] <b>강제 반응</b>: 닥터 옥토퍼스가 당신을 공격해 피해를 입힌 후, 각 음모에 위협을 1만큼 놓습니다. 활성 카운터를 활성화 순서상 다음 빌런에게 옮깁니다.\n<b>격파될 때</b>: 부가 음모 하나에서 위협을 4만큼 제거합니다 (플레이 영역에 다른 빌런이 없다면 대신 위협을 7만큼). 이 빌런을 따로 놓아둡니다.","star":true},{"id":"27095","name":"일렉트로","en":"* Electro","type":"villain","enc":true,"set":"Sinister Six","unique":true,"hp":8,"atk":1,"sch":2,"stage":1,"tr":["ACTIVATION ORDER 2"],"traits":["활성화 순서 2"],"text":"[star] <b>강제 반응</b>: 일렉트로가 당신을 공격해 피해를 입힌 후, 당신의 덱 맨 위에서 카드 7장을 버립니다. 활성 카운터를 활성화 순서상 다음 빌런에게 옮깁니다.\n<b>격파될 때</b>: 부가 음모 하나에서 위협을 4만큼 제거합니다 (플레이 영역에 다른 빌런이 없다면 대신 위협을 7만큼). 이 빌런을 따로 놓아둡니다.","star":true},{"id":"27096","name":"홉고블린","en":"* Hobgoblin","type":"villain","enc":true,"set":"Sinister Six","unique":true,"hp":9,"atk":1,"sch":2,"stage":1,"tr":["ACTIVATION ORDER 3"],"traits":["활성화 순서 3"],"text":"[star] <b>강제 반응</b>: 홉고블린이 당신을 공격해 피해를 입힌 후, 간접 피해 2점을 입습니다. 활성 카운터를 활성화 순서상 다음 빌런에게 옮깁니다.\n<b>격파될 때</b>: 부가 음모 하나에서 위협을 4만큼 제거합니다 (플레이 영역에 다른 빌런이 없다면 대신 위협을 7만큼). 이 빌런을 따로 놓아둡니다.","star":true},{"id":"27097","name":"크레이븐 더 헌터","en":"* Kraven the Hunter","type":"villain","enc":true,"set":"Sinister Six","unique":true,"hp":9,"atk":2,"sch":1,"stage":1,"tr":["ACTIVATION ORDER 4"],"traits":["활성화 순서 4"],"text":"[star] <b>강제 반응</b>: 크레이븐 더 헌터가 당신을 공격해 피해를 입힌 후, 당신이 조종하는 지원 카드나 업그레이드 1장을 선택해 버립니다. 활성 카운터를 활성화 순서상 다음 빌런에게 옮깁니다.\n<b>격파될 때</b>: 부가 음모 하나에서 위협을 4만큼 제거합니다 (플레이 영역에 다른 빌런이 없다면 대신 위협을 7만큼). 이 빌런을 따로 놓아둡니다.","star":true},{"id":"27098","name":"스콜피온","en":"* Scorpion","type":"villain","enc":true,"set":"Sinister Six","unique":true,"hp":10,"atk":3,"sch":0,"stage":1,"tr":["ACTIVATION ORDER 5"],"traits":["활성화 순서 5"],"text":"[star] <b>강제 반응</b>: 스콜피온이 당신을 공격해 피해를 입힌 후, 당신이 조종하는 캐릭터 하나를 기절시킵니다. 활성 카운터를 활성화 순서상 다음 빌런에게 옮깁니다.\n<b>격파될 때</b>: 부가 음모 하나에서 위협을 4만큼 제거합니다 (플레이 영역에 다른 빌런이 없다면 대신 위협을 7만큼). 이 빌런을 따로 놓아둡니다.","star":true},{"id":"27099","name":"벌처","en":"* Vulture","type":"villain","enc":true,"set":"Sinister Six","unique":true,"hp":7,"atk":2,"sch":1,"stage":1,"tr":["ACTIVATION ORDER 6"],"traits":["활성화 순서 6"],"text":"[star] <b>강제 반응</b>: 벌처가 당신을 공격해 피해를 입힌 후, 당신의 손에서 카드 1장을 선택해 버립니다. 활성 카운터를 활성화 순서상 다음 빌런에게 옮깁니다.\n<b>격파될 때</b>: 부가 음모 하나에서 위협을 4만큼 제거합니다 (플레이 영역에 다른 빌런이 없다면 대신 위협을 7만큼). 이 빌런을 따로 놓아둡니다.","star":true},{"id":"27100a","name":"사악한 동기화","en":"Sinister Synchronization","type":"main","enc":true,"set":"Sinister Six","unique":false,"stage":1,"tr":[],"traits":[],"text":"<b>구성</b>: 닥터 옥토퍼스, 일렉트로, 홉고블린, 크레이븐 더 헌터, 스콜피온, 벌처. 시니스터 식스, 게릴라 전술, 일반 조우 세트.\n<b>사전 준비</b>: 빌런 X명을 무작위로 선택합니다. X는 플레이어 수보다 1 많은 수입니다. 그 빌런들을 플레이 영역에 내려놓고, 활성화 순서 값이 가장 낮은 빌런에게 활성 카운터를 놓고, 나머지 빌런은 따로 놓아둡니다. 터널 끝의 빛 부가 음모를 [[함정!]] 면이 앞면이 되도록 플레이 영역에 내려놓습니다."},{"id":"27100b","name":"사악한 동기화","en":"Sinister Synchonization","type":"main","enc":true,"set":"Sinister Six","unique":false,"start":2,"startStar":true,"target":8,"targetStar":true,"esc":1,"escStar":true,"stage":1,"tr":[],"traits":[],"text":"매복! — <b>특수</b>: 따로 놓아둔 빌런 하나를 무작위로 선택해 플레이 영역에 내려놓고, 그 빌런에게 활성 카운터를 놓습니다. (전문가 모드에서는, 터널 끝의 빛에 위협을 2만큼 놓습니다.)\n<b>강제 난입</b>: 빌런이 활성화하려 할 때, 플레이 영역에 빌런이 없다면, 이 카드의 \"<i>매복!</i>\" 능력을 해결합니다. 그 활성화를 계속합니다."},{"id":"27101a","name":"사악한 몰매","en":"Sinister Beatdown","type":"main","enc":true,"set":"Sinister Six","unique":false,"stage":2,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 따로 놓아둔 빌런 하나를 무작위로 선택해 플레이 영역에 내려놓고, 그 빌런에게 활성 카운터를 놓습니다 <i>(다른 빌런이 카운터를 가지고 있더라도)</i>. 이렇게 플레이 영역에 들어온 빌런이 없거나 전문가 모드라면, 시작 플레이어에게 뒷면 조우 카드 1장을 나누어 줍니다."},{"id":"27101b","name":"사악한 몰매","en":"Sinister Beatdown","type":"main","enc":true,"set":"Sinister Six","unique":false,"start":3,"startStar":true,"target":7,"targetStar":true,"esc":1,"escStar":true,"stage":2,"tr":[],"traits":[],"text":"<i>매복!</i> — <b>특수</b>: 따로 놓아둔 빌런 하나를 무작위로 선택해 플레이 영역에 내려놓고, 그 빌런에게 활성 카운터를 놓습니다. (전문가 모드에서는, 터널 끝의 빛에 위협을 2만큼 놓습니다.)\n<b>강제 난입</b> 빌런이 활성화하려 할 때, 플레이 영역에 빌런이 없다면, 이 카드의 \"<i>매복!</i>\" 능력을 해결합니다. 그 활성화를 계속합니다.\n<b>이 스테이지가 완료되면, 플레이어들은 게임에서 패배합니다.</b>"},{"id":"27102a","name":"터널 끝의 빛","en":"Light at the End","type":"side","enc":true,"set":"Sinister Six","unique":false,"start":10,"tr":["TRAP!"],"permanent":1,"hinder":10,"hinderStar":true,"traits":["함정!"],"text":"영속. 교란 10[per_hero].\n플레이어들은 탈출하지 않는 한 승리할 수 없습니다.\n<b>강제 난입</b>: 이 음모에서 마지막 위협이 제거될 때, 주요 음모의 \"<i>매복!</i>\" 능력을 해결합니다. 이 카드를 뒤집습니다. <i>(플레이어들은 반대쪽 면에서 탈출할 수 있습니다.)</i>"},{"id":"27102b","name":"터널 끝의 빛","en":"Light at the End","type":"side","enc":true,"set":"Sinister Six","unique":false,"start":5,"hazard":1,"tr":["CHASE!"],"permanent":1,"hinder":10,"hinderStar":true,"traits":["추격!"],"text":"영속. 교란 10[per_hero].\n플레이어들은 탈출하지 않는 한 승리할 수 없습니다.\n<b>강제 난입</b>: 이 음모에서 마지막 위협이 제거될 때, 플레이어들은 탈출하고 게임에서 승리합니다."},{"id":"27103","name":"고양된 사기","en":"Heightened Morale","type":"attachment","enc":true,"set":"Sinister Six","unique":false,"tr":["CONDITION"],"traits":["상태"],"text":"활성화 순서 값이 가장 높은 빌런에게 장착합니다. 그럴 수 없다면, 주요 음모의 \"<i>매복!</i>\" 능력을 해결한 다음, 이 카드를 활성 빌런에게 장착합니다.\nX는 플레이 영역에 있는 빌런의 수와 같습니다."},{"id":"27104","name":"도발하는 존재","en":"Taunting Presence","type":"attachment","enc":true,"set":"Sinister Six","unique":false,"boost":2,"tr":["CONDITION"],"traits":["상태"],"text":"남은 생명력이 가장 많은 빌런에게 장착합니다. 그럴 수 없다면, 주요 음모의 매복! 능력을 해결한 다음, 이 카드를 활성 빌런에게 장착합니다."},{"id":"27105","name":"팀 리더","en":"Team Leader","type":"attachment","enc":true,"set":"Sinister Six","unique":false,"boost":1,"tr":["TITLE"],"crisis":1,"traits":["칭호"],"text":"활성화 순서 값이 가장 낮은 빌런에게 장착합니다. 그럴 수 없다면, 주요 음모의 매복! 능력을 해결한 다음, 이 카드를 활성 빌런에게 장착합니다."},{"id":"27106","name":"팀을 위한 희생","en":"Take One for the Team","type":"attachment","enc":true,"set":"Sinister Six","unique":false,"boost":1,"tr":[],"traits":[],"text":"공격 수치가 가장 높은 빌런에게 장착합니다. 그럴 수 없다면, 주요 음모의 매복! 능력을 해결한 다음, 이 카드를 활성 빌런에게 장착합니다.\n당신은 팀을 위한 희생이 장착되지 않은 빌런을 공격할 수 없습니다."},{"id":"27107","name":"완력 바리케이드","en":"Brute Force Barricade","type":"side","enc":true,"set":"Sinister Six","unique":false,"boost":2,"start":9,"tr":[],"victory":1,"traits":[],"text":"승점 1. <i>(격파되면, 이 카드를 승점 구역에 더합니다.)</i>\n다른 부가 음모에서는 위협을 제거할 수 없습니다.\n<hr />\n[star] <b>강화</b>: 이번 활성화에서 빌런에게 강화 카드 1장을 추가로 줍니다.","star":true,"boostStar":true},{"id":"27108","name":"상습 비행범","en":"Frequent Flyers","type":"treachery","enc":true,"set":"Sinister Six","unique":false,"boost":3,"tr":[],"traits":[],"text":"전문가 모드에서, 이 카드는 진척 1을 얻으며 무효화될 수 없습니다.\n<b>공개될 때</b>: 따로 놓아둔 홉고블린과 벌처를 플레이 영역에 내려놓습니다. 홉고블린이 이미 플레이 영역에 있다면, 간접 피해 2점을 입습니다. 벌처가 이미 플레이 영역에 있다면, 당신의 손에서 무작위로 카드 1장을 버립니다."},{"id":"27109","name":"하이 패션","en":"High Fashion","type":"treachery","enc":true,"set":"Sinister Six","unique":false,"boost":3,"tr":[],"traits":[],"text":"전문가 모드에서, 이 카드는 진척 1을 얻으며 무효화될 수 없습니다.\n<b>공개될 때</b>: 따로 놓아둔 일렉트로와 크레이븐 더 헌터를 플레이 영역에 내려놓습니다. 일렉트로가 이미 플레이 영역에 있다면, 당신이 조종하는 카드 중 비용이 가장 높은 카드를 버립니다. 크레이븐 더 헌터가 이미 플레이 영역에 있다면, 당신이 조종하는 카드 중 비용이 가장 낮은 카드를 버립니다."},{"id":"27110","name":"로봇 강화","en":"Robotic Enhancements","type":"treachery","enc":true,"set":"Sinister Six","unique":false,"boost":3,"tr":[],"traits":[],"text":"전문가 모드에서, 이 카드는 진척 1을 얻으며 무효화될 수 없습니다.\n<b>공개될 때</b>: 따로 놓아둔 닥터 옥토퍼스와 스콜피온을 플레이 영역에 내려놓습니다. 닥터 옥토퍼스가 이미 플레이 영역에 있다면, 당신이 조종하는 캐릭터 하나를 혼란에 빠뜨립니다. 스콜피온이 이미 플레이 영역에 있다면, 당신이 조종하는 캐릭터 하나를 기절시킵니다."},{"id":"27111","name":"고통의 동업","en":"Partnership of Pain","type":"treachery","enc":true,"set":"Sinister Six","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b>공개될 때 (일상): </b> 활성화 순서 값이 가장 낮은 빌런이 음모 +X로 암약합니다. X는 플레이 영역에 있는 다른 모든 빌런의 음모 합계입니다.\n<b> 공개될 때 (히어로): </b> 활성화 순서 값이 가장 높은 빌런이 공격 +X로 당신을 공격합니다. X는 플레이 영역에 있는 다른 모든 빌런의 공격 합계입니다."},{"id":"27112","name":"놀랐지!","en":"Surprise!","type":"treachery","enc":true,"set":"Sinister Six","unique":false,"boost":1,"tr":[],"traits":[],"text":"전문가 모드에서, 이 카드는 쇄도를 얻으며 무효화될 수 없습니다.\n<b>공개될 때</b>: 주요 음모의 매복! 능력을 해결합니다. 이렇게 플레이 영역에 들어온 빌런이 없다면, 터널 끝의 빛에 위협을 3만큼 놓습니다."},{"id":"27113","name":"베놈 고블린","en":"* Venom Goblin","type":"villain","enc":true,"set":"Venom Goblin","unique":true,"hp":16,"hpStar":true,"atk":2,"sch":2,"stage":1,"tr":["GOBLIN","SYMBIOTE"],"steady":1,"traits":["고블린","심비오트"],"text":"의연.\n<i>도시 감염</i> — [star] <b>강제 반응</b>: 베놈 고블린이 당신을 상대로 활성화한 후, 글라이더 카운터를 위협이 가장 적은 주요 음모로 옮깁니다. 그 음모에 위협을 2만큼 놓거나 그 음모의 \"<b>특수</b>\" 능력을 해결하는 것 중 하나를 선택합니다.","star":true},{"id":"27114","name":"베놈 고블린","en":"* Venom Goblin","type":"villain","enc":true,"set":"Venom Goblin","unique":true,"hp":18,"hpStar":true,"atk":3,"sch":2,"stage":2,"tr":["GOBLIN","SYMBIOTE"],"toughness":1,"steady":1,"traits":["고블린","심비오트"],"text":"의연. 강인.\n<b>공개될 때</b>: 각 플레이어에게 뒷면 조우 카드 2장을 나누어 줍니다.\n<i>왕좌 차지</i> — [star] <b>강제 반응</b>: 베놈 고블린이 당신을 상대로 활성화한 후, 글라이더 카운터를 위협이 가장 적은 주요 음모로 옮깁니다. 그 음모의 \"<b>특수</b>\" 능력을 해결합니다.","star":true},{"id":"27115","name":"베놈 고블린","en":"* Venom Goblin","type":"villain","enc":true,"set":"Venom Goblin","unique":true,"hp":21,"hpStar":true,"atk":3,"sch":3,"stage":3,"retaliate":1,"tr":["GOBLIN","SYMBIOTE"],"toughness":1,"stalwart":1,"traits":["고블린","심비오트"],"text":"반격 1. 견고. 강인.\n<b>공개될 때</b>: 각 플레이어에게 뒷면 조우 카드 3장을 나누어 줍니다.\n<i>공포 정치</i> — [star] <b>강제 반응</b>: 베놈 고블린이 당신을 상대로 활성화한 후, 글라이더 카운터를 위협이 가장 적은 주요 음모로 옮깁니다. 그 음모에 위협을 1만큼 놓고 그 음모의 \"<b>특수</b>\" 능력을 해결합니다.","star":true},{"id":"27116a","name":"뉴욕의 하늘","en":"Skies Over New York","type":"main","enc":true,"set":"Venom Goblin","unique":false,"stage":1,"tr":[],"traits":[],"text":"<b>구성</b>: 베놈 고블린 (I), 베놈 고블린 (II) <i>(전문가 모드에서는 베놈 고블린 (II), 베놈 고블린 (III).)</i> 베놈 고블린, 심비오트의 힘, 일반 조우 세트. 모듈식 조우 세트 하나 <i>(고블린 장비)</i>.\n<b>사전 준비</b>: 로어 맨해튼, 미드타운 맨해튼, 어퍼 맨해튼 주요 음모를 플레이 영역에 내려놓습니다. 글라이더 카운터를 미드타운 맨해튼에 놓습니다. 이 카드를 뒤집어 따로 놓아둡니다."},{"id":"27116b","name":"뉴욕의 하늘","en":"Skies Over New York","type":"environment","enc":true,"set":"Venom Goblin","unique":false,"tr":[],"traits":[],"text":"주요 음모에 영향을 주는 플레이어 카드는 아무 주요 음모에나 적용할 수 있습니다.\n주요 음모에 영향을 주는 조우 카드는 글라이더 카운터가 있는 음모에만 적용됩니다 (가속 토큰을 놓는 것 포함).\n각 주요 음모는 매 라운드 자신의 가속 값과 그 음모에 놓인 가속 토큰에 따라 위협이 쌓입니다."},{"id":"27117a","name":"로어 맨해튼","en":"Lower Manhattan","type":"main","enc":true,"set":"Venom Goblin","unique":false,"start":1,"startStar":true,"target":11,"targetStar":true,"esc":1,"escStar":true,"stage":1,"tr":[],"traits":[],"text":"<b>특수</b>: 각 음모에 위협을 1만큼 놓습니다. [[심비오트]] 환경이 플레이 영역에 있다면, 이 음모에 위협을 1만큼 추가로 놓습니다."},{"id":"27117b","name":"로어 맨해튼","en":"Lower Manhattan","type":"environment","enc":true,"set":"Venom Goblin","unique":false,"tr":["LOCATION","SYMBIOTE"],"traits":["장소","심비오트"],"text":"<b>공개될 때</b>: 글라이더 카운터와 모든 가속 토큰을 이 카드에서 위협이 가장 적은 주요 음모로 옮깁니다.\n<b>플레이 영역에 [[심비오트]] 환경이 2개 이상 있다면, 플레이어들은 게임에서 패배합니다.</b>"},{"id":"27118a","name":"미드타운 맨해튼","en":"Midtown Manhattan","type":"main","enc":true,"set":"Venom Goblin","unique":false,"start":2,"startStar":true,"target":12,"targetStar":true,"esc":1,"escStar":true,"stage":1,"tr":[],"traits":[],"text":"<b>특수</b>: 간접 피해 2점을 입습니다. [[심비오트]] 환경이 플레이 영역에 있다면, 간접 피해 1점을 추가로 입습니다."},{"id":"27118b","name":"미드타운 맨해튼","en":"Midtown Manhattan","type":"environment","enc":true,"set":"Venom Goblin","unique":false,"tr":["LOCATION","SYMBIOTE"],"traits":["장소","심비오트"],"text":"<b>공개될 때</b>: 글라이더 카운터와 모든 가속 토큰을 이 카드에서 위협이 가장 적은 주요 음모로 옮깁니다.\n<b>플레이 영역에 [[심비오트]] 환경이 2개 이상 있다면, 플레이어들은 게임에서 패배합니다.</b>"},{"id":"27119a","name":"어퍼 맨해튼","en":"Upper Manhattan","type":"main","enc":true,"set":"Venom Goblin","unique":false,"start":0,"target":10,"targetStar":true,"esc":1,"escStar":true,"stage":1,"tr":[],"traits":[],"text":"<b>특수</b>: 당신의 손에서 카드 1장을 버립니다. [[심비오트]] 환경이 플레이 영역에 있다면, 당신의 덱 맨 위에서 카드 4장을 버립니다."},{"id":"27119b","name":"어퍼 맨해튼","en":"Upper Manhattan","type":"environment","enc":true,"set":"Venom Goblin","unique":false,"tr":["LOCATION","SYMBIOTE"],"traits":["장소","심비오트"],"text":"<b>공개될 때</b>: 글라이더 카운터와 모든 가속 토큰을 이 카드에서 위협이 가장 적은 주요 음모로 옮깁니다.\n<b>플레이 영역에 [[심비오트]] 환경이 2개 이상 있다면, 플레이어들은 게임에서 패배합니다.</b>"},{"id":"27120","name":"우리는 하나다","en":"We Are One","type":"attachment","enc":true,"set":"Venom Goblin","unique":false,"boost":3,"plus":{"atk":3,"sch":3},"tr":[],"traits":[],"text":"베놈 고블린에게 장착합니다.\n<b>히어로 행동</b>: 인쇄된 [energy][mental][physical] 자원을 소모 → 이 카드를 버림."},{"id":"27121","name":"심비오트 광전사","en":"Symbiotic Berserker","type":"minion","enc":true,"set":"Venom Goblin","unique":false,"hp":5,"atk":3,"sch":0,"tr":["SYMBIOTE"],"traits":["심비오트"],"text":"[star] [[심비오트]] 환경이 플레이 영역에 있는 동안, 심비오트 광전사는 속공을 얻습니다.\n<hr />\n[star] <b>강화</b>: 글라이더 카운터를 위협이 가장 많은 주요 음모로 옮깁니다. 그 음모에 위협을 1만큼 놓습니다.","star":true,"boostStar":true},{"id":"27122","name":"심비오트 괴물","en":"Symbiotic Monstrosity","type":"minion","enc":true,"set":"Venom Goblin","unique":false,"hp":6,"atk":2,"sch":2,"boost":3,"retaliate":1,"tr":["ELITE","SYMBIOTE"],"toughness":1,"steady":1,"traits":["간부","심비오트"],"text":"반격 1. 의연. 강인.\n[star] [[심비오트]] 환경이 플레이 영역에 있는 동안, 심비오트 괴물은 생명력 +3을 받습니다.\n<hr />\n[star] <b>강화</b>: 이 활성화가 공격이라면, 이 공격은 간접 피해를 입힙니다.","star":true,"boostStar":true},{"id":"27123","name":"심비오트 노예","en":"Symbiotic Thrall","type":"minion","enc":true,"set":"Venom Goblin","unique":false,"hp":4,"atk":2,"sch":1,"tr":["SYMBIOTE"],"guard":1,"traits":["심비오트"],"text":"경호.\n[[심비오트]] 환경이 플레이 영역에 있는 동안, 심비오트 노예는 순찰을 얻습니다.\n<hr />\n[star] <b>강화</b>: 글라이더 카운터가 없는 각 주요 음모에 위협을 1만큼 놓습니다.","star":true,"boostStar":true},{"id":"27124","name":"곪아가는 덩어리","en":"Festering Mass","type":"side","enc":true,"set":"Venom Goblin","unique":false,"start":5,"accel":1,"tr":[],"traits":[],"text":"플레이 영역에 다른 [[심비오트]] 환경이 없는 동안, 이 카드는 [[심비오트]] 환경으로 간주합니다.\n<hr />\n[star] <b>강화</b>: 이 카드를 공개합니다.","star":true,"boostStar":true},{"id":"27125","name":"광란의 드라이브","en":"Joy Ride","type":"side","enc":true,"set":"Venom Goblin","unique":false,"boost":2,"start":2,"hazard":1,"tr":[],"hinder":2,"hinderStar":true,"traits":[],"text":"교란 2[per_hero].\n<b>공개될 때</b>: 글라이더 토큰을 위협이 가장 많은 주요 음모로 옮깁니다. 그 음모의 \"<b>특수</b>\" 능력을 해결합니다."},{"id":"27126","name":"확산되는 공황","en":"Spreading Panic","type":"treachery","enc":true,"set":"Venom Goblin","unique":false,"surge":1,"tr":[],"traits":[],"text":"쇄도.\n<b>공개될 때</b>: 글라이더 카운터가 있는 음모의 \"<b>특수</b>\" 능력을 해결합니다.\n<hr />\n[star] <b>강화</b>: 글라이더 카운터가 있는 음모의 \"<b>특수</b>\" 능력을 해결합니다.","star":true,"boostStar":true},{"id":"27127","name":"거리의 공황","en":"Panic in the Streets","type":"side","enc":true,"set":"City in Chaos","unique":false,"boost":2,"start":5,"accel":1,"tr":[],"traits":[],"text":"각 [[장소]] 지원 카드와 각 [[페르소나]] 지원 카드의 인쇄된 문구 상자는 비어 있는 것으로 간주합니다 <i>([[특성]] 제외)</i>."},{"id":"27128","name":"라이노","en":"* Rhino","type":"minion","enc":true,"set":"City in Chaos","unique":true,"hp":8,"atk":3,"sch":0,"boost":3,"tr":["CRIMINAL","ELITE"],"steady":1,"traits":["범죄자","간부"],"text":"의연. (의연 캐릭터를 기절시키거나 혼란에 빠뜨리려면 같은 종류의 상태 카드가 2장 필요합니다.)\n[star] 라이노의 공격은 압살과 관통을 얻습니다.","star":true},{"id":"27129","name":"빚 받아내기","en":"Calling in Favors","type":"treachery","enc":true,"set":"City in Chaos","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 라이노가 음모 +2로 암약합니다. 라이노가 플레이 영역에 없다면, 조우 덱과 버린 조우 더미에서 라이노 하수인을 찾아 당신과 교전 중인 채로 플레이 영역에 내려놓습니다. (덱을 섞습니다.)"},{"id":"27130","name":"지금 아니면 안 돼","en":"Now or Never","type":"treachery","enc":true,"set":"City in Chaos","unique":false,"boost":1,"tr":[],"peril":1,"traits":[],"text":"고립. (당신이 이 카드를 해결하는 동안, 다른 플레이어들은 당신을 도울 수 없습니다.)\n<b> 공개될 때: </b> 다음 중 하나를 선택:\n주요 음모에 가속 토큰 1개를 놓습니다.\n당신이 조종하는 캐릭터 하나를 소진하고 아무 유형의 자원 1개를 소모합니다."},{"id":"27131","name":"잡범","en":"Common Criminal","type":"minion","enc":true,"set":"Down to Earth","unique":false,"hp":3,"atk":1,"sch":0,"boost":1,"surge":1,"tr":["CRIMINAL"],"traits":["범죄자"],"text":"쇄도.\n<b> 일상 행동: </b> [physical] 자원을 소모 → 잡범에게 피해 3점을 입힘. 이 하수인이 이렇게 격파되었다면, 카드 1장을 뽑거나 부가 음모 하나에서 위협을 3만큼 제거하는 것 중 하나를 선택."},{"id":"27132","name":"친구와 가족","en":"Friends and Family","type":"obligation","enc":true,"set":"Down to Earth","unique":false,"boost":3,"tr":[],"traits":[],"text":"히어로 형태인 동안, 당신이 플레이하는 각 이벤트의 자원 비용을 1만큼 증가시킵니다.\n<b> 일상 행동: </b> 당신의 손에서 아이덴티티 전용 카드 1장을 버림 → 이 의무 카드를 버림."},{"id":"27133","name":"자원봉사","en":"Volunteer Work","type":"side","enc":true,"set":"Down to Earth","unique":false,"boost":2,"start":3,"startStar":true,"accel":1,"tr":[],"traits":[],"text":"당신은 이 음모를 저지할 수 없습니다.\n<b>일상 행동</b>: 아무 유형의 자원 2개를 소모 → 당신의 일상 형태의 회복 값만큼 이 음모에서 위협을 제거. 당신의 아이덴티티가 [[시민]] 특성을 가지고 있다면, 카드 1장을 뽑음."},{"id":"27134","name":"\"위협인가, 위험인가?\"","en":"\"Threat or Menace?\"","type":"treachery","enc":true,"set":"Down to Earth","unique":false,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 당신은 형태를 바꿀 수 있습니다. 당신이 히어로 형태라면, 주요 음모에 위협을 2만큼 놓습니다. 당신이 일상 형태라면, 당신의 다음 차례 동안 형태를 바꿀 수 없습니다."},{"id":"27135","name":"미결 사항","en":"Loose Ends","type":"treachery","enc":true,"set":"Down to Earth","unique":false,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 조우 덱, 버린 조우 더미, 따로 놓아둔 영역, 게임에서 제거된 영역에서 당신의 의무 카드 1장을 찾아 공개합니다. 그 공개 중에 당신이 일상 형태로 변신한다면, 당신의 손에서 무작위로 카드 1장을 버립니다. 이렇게 당신의 의무 카드가 공개되지 않았다면, 이 카드는 쇄도를 얻습니다."},{"id":"27136","name":"개량형 글라이더","en":"Advanced Glider","type":"attachment","enc":true,"set":"Goblin Gear","unique":false,"boost":3,"tr":["ITEM","TECH"],"traits":["도구","과학"],"text":"빌런에게 장착합니다.\n<b>강제 반응</b>: 장착된 빌런이 당신을 상대로 활성화한 후, 그 빌런은 당신을 상대로 다시 활성화합니다(플레이어마다 라운드마다 1회 제한).\n<b>히어로 행동</b>: 당신의 손에서 자원 비용의 합이 3 이상인 [[공격]] 카드를 원하는 만큼 버림 → 이 카드를 버림."},{"id":"27137","name":"충격 폭탄","en":"Concussive Bombs","type":"attachment","enc":true,"set":"Goblin Gear","unique":false,"boost":2,"plus":{"atk":1},"tr":["TECH","WEAPON"],"uses":{"n":2,"kind":"bomb"},"traits":["과학","무기"],"text":"빌런에게 장착합니다.\n사용(폭탄 카운터 2).\n[star] <b>강제 반응: </b> 빌런이 당신을 공격한 후, 이 카드에서 폭탄 카운터를 1만큼 제거 → 당신이 조종하는 업그레이드 1장과 지원 1장을 소진.","star":true},{"id":"27138","name":"소이탄","en":"Incendiary Bombs","type":"attachment","enc":true,"set":"Goblin Gear","unique":false,"boost":1,"plus":{"atk":1},"tr":["TECH","WEAPON"],"uses":{"n":2,"kind":"bomb"},"traits":["과학","무기"],"text":"빌런에게 장착합니다.\n사용(폭탄 카운터 2).\n[star] <b>강제 반응: </b> 빌런이 당신을 공격한 후, 이 카드에서 폭탄 카운터를 1만큼 제거 → 간접 피해 2점을 입음.","star":true},{"id":"27139","name":"연막탄","en":"Smoke Bombs","type":"attachment","enc":true,"set":"Goblin Gear","unique":false,"boost":1,"plus":{"atk":1},"tr":["TECH","WEAPON"],"uses":{"n":2,"kind":"bomb"},"traits":["과학","무기"],"text":"빌런에게 장착합니다.\n사용(폭탄 카운터 2).\n[star] <b>강제 반응: </b> 빌런이 당신을 공격한 후, 이 카드에서 폭탄 카운터를 1만큼 제거 → 당신의 손에서 비용이 가장 낮은 이벤트 1장을 버림.","star":true},{"id":"27140","name":"무한 공급","en":"Limitless Supply","type":"side","enc":true,"set":"Goblin Gear","unique":false,"boost":3,"start":5,"hazard":1,"tr":[],"traits":[],"text":"각 [[과학]] 장착 카드는 쇄도를 얻습니다."},{"id":"27141","name":"원격 조종","en":"Remote Navigation","type":"treachery","enc":true,"set":"Goblin Gear","unique":false,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 개량형 글라이더가 플레이 영역에 있다면, 빌런이 당신을 상대로 활성화합니다. 플레이 영역에 없다면, 조우 덱과 버린 조우 더미에서 개량형 글라이더를 찾아 공개합니다.\n<hr />\n[star] <b>강화</b>: 이번 활성화에서 빌런에게 강화 카드 2장을 추가로 줍니다.","star":true,"boostStar":true},{"id":"27142","name":"실물 크기 디코이","en":"Life-Size Decoy","type":"minion","enc":true,"set":"Guerrilla Tactics","unique":false,"hp":5,"atk":0,"sch":0,"tr":[],"traits":[],"text":"전문가 모드에서, 실물 크기 디코이는 강인을 얻습니다.\n교전 중인 플레이어는 부가 음모를 저지할 수 없습니다.\n<hr />\n[star] <b>강화</b>: 이 하수인을 당신과 교전 중인 채로 플레이 영역에 내려놓습니다.","star":true,"boostStar":true},{"id":"27143","name":"합동 작전","en":"Coordinated Effort","type":"side","enc":true,"set":"Guerrilla Tactics","unique":false,"boost":1,"start":6,"tr":[],"traits":[],"text":"각 적은 가속 아이콘([acceleration])을 1개 얻습니다.\n<hr />\n[star] <b>강화</b>: 각 음모에 위협을 1만큼 놓습니다. (전문가 모드에서는 주요 음모에 위협을 1만큼 추가로 놓습니다.)","star":true,"boostStar":true},{"id":"27144","name":"그림자 속에 숨어","en":"Hidden in Shadow","type":"side","enc":true,"set":"Guerrilla Tactics","unique":false,"boost":1,"start":4,"tr":[],"traits":[],"text":"각 적은 수렁 아이콘([hazard])을 1개 얻습니다.\n<hr />\n[star] <b>강화</b>: 각 플레이어에게 간접 피해 1점을 입힙니다. (전문가 모드에서는 시작 플레이어에게 간접 피해 1점을 추가로 입힙니다.)","star":true,"boostStar":true},{"id":"27145","name":"팀워크가 꿈을 이룬다","en":"Teamwork Makes the Dream Work","type":"side","enc":true,"set":"Guerrilla Tactics","unique":false,"boost":2,"start":5,"tr":[],"traits":[],"text":"각 적은 음모 +1과 공격 +1을 받습니다.\n<hr />\n[star] <b>강화</b>: 전문가 모드에서, 이번 활성화 동안 이 카드는 강화 아이콘 +2개 [boost][boost]를 받습니다.","star":true,"boostStar":true},{"id":"27146","name":"사방에서","en":"From Every Direction","type":"treachery","enc":true,"set":"Guerrilla Tactics","unique":false,"tr":[],"traits":[],"text":"전문가 모드에서, 이 카드는 쇄도를 얻습니다.\n<b>공개될 때</b>: 플레이 영역에 있는 적마다 주요 음모에 위협을 1만큼 놓습니다."},{"id":"27147","name":"팔 대포","en":"Arm Cannon","type":"attachment","enc":true,"set":"Osborn Tech","unique":false,"boost":3,"surge":1,"tr":["TECH","WEAPON"],"traits":["과학","무기"],"text":"쇄도.\n빌런에게 장착합니다.\n[star] 장착된 빌런의 공격은 압살과 관통을 얻습니다.\n<b>히어로 행동</b>: 당신이 조종하는 업그레이드 중 비용이 가장 높은 업그레이드를 버림 → 이 카드를 버림.","star":true},{"id":"27148","name":"이온 부츠","en":"Ionic Boots","type":"attachment","enc":true,"set":"Osborn Tech","unique":false,"boost":3,"surge":1,"tr":["ITEM","TECH"],"traits":["도구","과학"],"text":"쇄도.\n빌런에게 장착합니다.\n[star] <b>강제 반응</b>: 장착된 빌런이 공격하여 당신의 아이덴티티에게 피해를 입힌 후, 주요 음모에 위협을 2만큼 놓습니다.\n<b>히어로 행동</b>: [energy] [mental][physical] 자원을 소모 → 이 카드를 버림.","star":true},{"id":"27149","name":"운동 에너지 갑옷","en":"Kinetic Armor","type":"attachment","enc":true,"set":"Osborn Tech","unique":false,"boost":3,"surge":1,"tr":["ARMOR","TECH"],"traits":["갑옷","과학"],"text":"쇄도.\n빌런에게 장착합니다.\n장착된 빌런은 반격 1을 얻습니다.\n<b>히어로 행동</b>: 간접 피해 3점을 입음 → 이 카드를 버림."},{"id":"27150","name":"네오카본 비늘","en":"Neocarbon Scales","type":"attachment","enc":true,"set":"Osborn Tech","unique":false,"boost":3,"surge":1,"tr":["ARMOR","TECH"],"traits":["갑옷","과학"],"text":"쇄도.\n빌런에게 장착합니다.\n장착된 빌런이 각 공격으로 입는 피해를 1만큼 감소시킵니다.\n<b>히어로 행동</b>: 빌런에게 강인함 상태 카드와 뒷면 강화 카드 1장을 줌 → 이 카드를 버림."},{"id":"27151","name":"가시 건틀렛","en":"Spiked Gauntlet","type":"attachment","enc":true,"set":"Osborn Tech","unique":false,"boost":3,"plus":{"atk":1},"surge":1,"tr":["TECH","WEAPON"],"traits":["과학","무기"],"text":"쇄도.\n빌런에게 장착합니다.\n<b>히어로 행동</b>: 빌런이 당신을 공격합니다. 그 공격이 끝난 후, 당신의 아이덴티티가 그 공격으로 피해를 입지 않았다면, 이 카드를 버립니다."},{"id":"27152","name":"추적 디스플레이","en":"Tracking Display","type":"attachment","enc":true,"set":"Osborn Tech","unique":false,"boost":3,"surge":1,"tr":["ITEM","TECH"],"traits":["도구","과학"],"text":"쇄도.\n빌런에게 장착합니다.\n[star] 어떤 캐릭터도 장착된 빌런의 공격을 방어할 수 없습니다.\n<b>히어로 행동</b>: 당신이 조종하는 캐릭터 하나를 소진하고 당신의 손에서 무작위로 카드 1장을 버림 → 이 카드를 버림.","star":true},{"id":"27153","name":"유도된 공황","en":"Induced Panic","type":"attachment","enc":true,"set":"Personal Nightmare","unique":false,"boost":1,"tr":["ILLUSION"],"traits":["환영"],"text":"당신의 아이덴티티에 장착합니다.\n당신은 당신의 히어로의 인쇄된 글 상자에 있는 유발 능력을 해결할 수 없습니다. (유발 능력은 <b> 굵은 글씨 </b>로 된 타이밍 유발 문구가 있는 능력입니다.)\n<b>일상 행동</b>: 당신의 손에서 무작위로 아이덴티티 전용 카드 1장을 버림 → 이 카드를 버림."},{"id":"27154","name":"사악한 도플갱어","en":"Evil Doppelgänger","type":"minion","enc":true,"set":"Personal Nightmare","unique":false,"hp":5,"atk":1,"sch":1,"boost":2,"tr":["ILLUSION"],"traits":["환영"],"text":"사악한 도플갱어는 음모 +X와 공격 +X를 받습니다. X는 교전 중인 플레이어의 손에 있는 아이덴티티 전용 카드의 수입니다.\n<hr />\n[star] <b>강화</b>: 카드 3장을 뽑습니다. 당신의 손에서 무작위로 카드 3장을 버립니다.","star":true,"boostStar":true},{"id":"27155","name":"바보의 낙원","en":"Fool's Paradise","type":"side","enc":true,"set":"Personal Nightmare","unique":false,"boost":3,"start":6,"startStar":true,"hazard":1,"accel":1,"tr":[],"crisis":1,"victory":1,"traits":[],"text":"승점 1. <i>(격파되면, 이 카드를 승점 구역에 더합니다.)</i>\n각 아이덴티티는 손 크기 +2를 받습니다."},{"id":"27156","name":"내부의 약점","en":"Weakness from Within","type":"side","enc":true,"set":"Personal Nightmare","unique":false,"boost":2,"start":1,"hazard":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 당신의 손에 있는 카드마다 이 카드에 위협을 1만큼 추가로 놓습니다."},{"id":"27157","name":"가장 깊은 공포","en":"Deepest Fears","type":"treachery","enc":true,"set":"Personal Nightmare","unique":false,"tr":[],"peril":1,"traits":[],"text":"고립. (당신이 이 카드를 해결하는 동안, 다른 플레이어들은 당신을 도울 수 없습니다.)\n<b>공개될 때</b>: 당신의 손에 있는 카드의 수만큼 당신의 덱 맨 위에서 카드를 버립니다. 이렇게 버려진 카드 중 아이덴티티 전용 카드가 1장 이상이라면, 주요 음모에 위협을 1만큼 놓습니다. 이렇게 버려진 아이덴티티 전용 카드가 없다면, 피해 1점을 입습니다."},{"id":"27158","name":"닥터 옥토퍼스","en":"Doctor Octopus","type":"minion","enc":true,"set":"Sinister Assault","unique":false,"hp":6,"atk":2,"sch":2,"boost":3,"tr":["ELITE","GENIUS"],"incite":2,"villainous":1,"traits":["간부","천재"],"text":"진척 2. 악당.\n[star] <b>강제 반응</b>: 닥터 옥토퍼스가 당신을 상대로 활성화한 후, 각 음모에 위협을 1만큼 놓습니다.","star":true},{"id":"27159","name":"일렉트로","en":"Electro","type":"minion","enc":true,"set":"Sinister Assault","unique":false,"hp":6,"atk":1,"sch":2,"boost":3,"retaliate":1,"tr":["CRIMINAL","ELITE"],"villainous":1,"traits":["범죄자","간부"],"text":"반격 1. 악당.\n[star] <b>강제 반응</b>: 일렉트로가 당신과 교전하거나 당신을 상대로 활성화한 후, [energy] 또는 [wild] 자원을 버릴 때까지 당신의 덱 맨 위에서 카드를 버립니다.","star":true},{"id":"27160","name":"홉고블린","en":"Hobgoblin","type":"minion","enc":true,"set":"Sinister Assault","unique":false,"hp":6,"atk":2,"sch":1,"boost":3,"tr":["AERIAL","ELITE"],"villainous":1,"patrol":1,"traits":["공중","간부"],"text":"순찰. 악당.\n[star] <b>강제 반응</b>: 홉고블린이 당신을 공격한 후, 간접 피해 2점을 입습니다.","star":true},{"id":"27161","name":"크레이븐 더 헌터","en":"Kraven the Hunter","type":"minion","enc":true,"set":"Sinister Assault","unique":false,"hp":6,"atk":2,"sch":1,"boost":3,"tr":["ELITE"],"villainous":1,"steady":1,"traits":["간부"],"text":"의연. 악당.\n[star] <b>강제 반응</b>: 크레이븐 더 헌터가 공격하여 당신이 조종하는 캐릭터에게 피해를 입힌 후, 당신이 조종하는 업그레이드 또는 지원 1장을 버립니다.","star":true},{"id":"27162","name":"스콜피온","en":"Scorpion","type":"minion","enc":true,"set":"Sinister Assault","unique":false,"hp":6,"atk":3,"sch":1,"boost":3,"tr":["BRUTE","ELITE"],"toughness":1,"villainous":1,"traits":["야만","간부"],"text":"강인. 악당.\n[star] <b>강제 반응</b>: 스콜피온이 공격하여 캐릭터에게 피해를 입힌 후, 그 캐릭터를 기절시킵니다. 그 캐릭터가 이미 기절했다면, 그 캐릭터에게 피해 2점을 입힙니다.","star":true},{"id":"27163","name":"벌처","en":"Vulture","type":"minion","enc":true,"set":"Sinister Assault","unique":false,"hp":6,"atk":1,"sch":1,"boost":3,"tr":["AERIAL","ELITE"],"quickstrike":1,"villainous":1,"traits":["공중","간부"],"text":"속공. 악당.\n[star] <b>강제 반응</b>: 벌처가 당신을 상대로 활성화한 후, 당신의 손에서 무작위로 카드 1장을 버립니다.","star":true},{"id":"27164","name":"즉석 무기","en":"Improvised Weapons","type":"attachment","enc":true,"set":"Symbiotic Strength","unique":false,"boost":1,"tr":[],"amplify":1,"traits":[],"text":"빌런에게 장착합니다.\n<b>히어로 행동</b>: [mental][physical][energy] 자원을 소모 → 이 카드를 버림."},{"id":"27165","name":"폭력적 성향","en":"Violent Tendencies","type":"attachment","enc":true,"set":"Symbiotic Strength","unique":false,"boost":2,"tr":["CONDITION"],"traits":["상태"],"text":"빌런에게 장착합니다.\n<b>강제 반응</b>: 장착된 빌런이 공격으로 피해를 입은 후, 장착된 빌런에게 뒷면 강화 카드 1장을 줍니다. 그 공격이 장착된 빌런에게 피해를 3점 이상 입혔다면, 이 카드를 버립니다."},{"id":"27166","name":"거미줄 포획","en":"Webbed Up","type":"attachment","enc":true,"set":"Symbiotic Strength","unique":false,"tr":["CONDITION"],"traits":["상태"],"text":"당신의 아이덴티티에 장착합니다.\n<b>강제 난입</b>: 당신의 히어로가 공격하려 할 때, 대신 거미줄 포획을 버립니다. 그러고 나서 당신은 기절합니다.\n<hr />\n[star] <b>강화</b>: 당신은 기절합니다. 당신이 이미 기절했다면, 피해 2점을 입습니다.","star":true,"boostStar":true},{"id":"27167","name":"격노한 심비오트","en":"Enraged Symbiote","type":"minion","enc":true,"set":"Symbiotic Strength","unique":false,"hp":2,"atk":2,"sch":1,"tr":["SYMBIOTE"],"guard":1,"patrol":1,"traits":["심비오트"],"text":"경호. 순찰. (이 하수인이 당신과 교전 중인 한, 당신은 주요 음모를 저지할 수 없습니다.)\n<hr />\n[star] <b>강화</b>: 격노한 심비오트를 당신과 교전 중인 채로 플레이 영역에 내려놓습니다.","star":true,"boostStar":true},{"id":"27168","name":"스윙 공격","en":"Swinging Assault","type":"treachery","enc":true,"set":"Symbiotic Strength","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b> 공개될 때(일상): </b> 히어로 형태로 변신합니다. 빌런이 당신을 공격합니다.\n<b>공개될 때(히어로): </b> 빌런이 당신을 공격합니다. 이번 활성화에서 빌런에게 강화 카드 1장을 추가로 줍니다."},{"id":"27169","name":"불안정한 자아","en":"Unstable Sentience","type":"treachery","enc":true,"set":"Symbiotic Strength","unique":false,"surge":1,"tr":[],"traits":[],"text":"쇄도.\n<b>공개될 때</b>: 빌런에게 뒷면 강화 카드 1장을 줍니다.\n<hr />\n[star] <b>강화</b>: 이번 활성화가 공격이라면, 이번 공격 동안 이 카드는 강화 아이콘 +2개([boost][boost])를 받고 이 공격은 압살을 얻습니다.","star":true,"boostStar":true},{"id":"27170","name":"공모 망상","en":"Delusion of Collusion","type":"attachment","enc":true,"set":"Whispers of Paranoia","unique":false,"boost":1,"tr":["ILLUSION"],"traits":["환영"],"text":"당신의 아이덴티티에 장착합니다.\n당신은 당신이 조종하는 동료나 [[페르소나]] 지원을 준비할 수 없습니다.\n<b> 일상 행동: </b> 당신이 조종하는 동료 또는 [[페르소나]] 지원 1장을 버림 → 이 카드를 버림.\n<hr />\n[star] <b>강화</b>: 이 공격으로 동료가 격파되었다면, 그 동료에 인쇄된 비용만큼 간접 피해를 입습니다.","star":true,"boostStar":true},{"id":"27171","name":"조종당한 정신","en":"Manipulated Mind","type":"attachment","enc":true,"set":"Whispers of Paranoia","unique":false,"boost":2,"tr":["ILLUSION"],"traits":["환영"],"text":"장착된 동료를 글 상자가 비어 있는 하수인으로 취급합니다([[특성]] 제외). 장착된 하수인의 음모는 그 하수인에 인쇄된 저지 수치와 같으며, 그 하수인은 부수적 피해를 입지 않습니다.\n<b>공개될 때</b>: 당신이 조종하는 동료 중 비용이 가장 낮은 동료에게 장착합니다. 장착된 동료는 그 동료를 조종하던 플레이어와 교전합니다. 그렇게 할 수 없다면, 이 카드는 쇄도를 얻습니다."},{"id":"27172","name":"묵은 원한","en":"Old Grudge","type":"attachment","enc":true,"set":"Whispers of Paranoia","unique":false,"boost":2,"tr":["ILLUSION"],"traits":["환영"],"text":"장착된 하수인은 생명력 +1을 받습니다.\n<b>공개될 때</b>: 조우 덱, 버린 조우 더미, 따로 놓아둔 영역에서 당신의 숙적 하수인을 찾아 공개합니다. 묵은 원한을 그 하수인에게 장착합니다. (섞습니다.)\n<hr />\n[star] <b>강화</b>: 당신이 조종하는 각 캐릭터에게 피해 1점을 입힙니다.","star":true,"boostStar":true},{"id":"27173","name":"분석 마비","en":"Analysis Paralysis","type":"side","enc":true,"set":"Whispers of Paranoia","unique":false,"boost":3,"start":1,"tr":[],"amplify":1,"traits":[],"text":"<b>공개될 때</b>: 조우 덱, 버린 조우 더미, 따로 놓아둔 영역에서 당신의 숙적 부가 음모를 찾아 공개합니다. 이 카드에 위협을 X만큼 추가로 놓습니다. X는 그 부가 음모에 놓인 위협의 양입니다."},{"id":"27174a","name":"대중의 항의","en":"Public Outcry","type":"environment","enc":true,"set":"Bad Publicity","unique":false,"accel":1,"tr":["STANDARD MODE ONLY"],"uses":{"n":2,"kind":"notoriety","star":true},"victory":1,"traits":["표준 모드 전용"],"text":"승점 1. 사용(악명 카운터 2[per_hero]).\n<b>반응</b>: 하수인이나 부가 음모가 격파된 후, 이 카드에서 악명 카운터를 1만큼 제거합니다."},{"id":"27174b","name":"대중의 항의","en":"Public Outcry","type":"environment","enc":true,"set":"Bad Publicity","unique":false,"hazard":1,"tr":["EXPERT MODE ONLY"],"uses":{"n":3,"kind":"notoriety","star":true},"victory":1,"traits":["전문가 모드 전용"],"text":"승점 1. 사용(악명 카운터 3[per_hero]).\n<b>반응</b>: 하수인이나 부가 음모가 격파된 후, 이 카드에서 악명 카운터를 1만큼 제거합니다."},{"id":"27175","name":"흑색선전","en":"Smear Campaign","type":"treachery","enc":true,"set":"Bad Publicity","unique":false,"boost":3,"tr":[],"traits":[],"text":"전문가 모드에서, 이 카드는 쇄도를 얻습니다.\n<b>공개될 때</b>: 대중의 항의가 플레이 영역에 있다면, 그 카드에 악명 카운터를 2만큼 놓은 다음 이 카드를 게임에서 제거합니다. 대중의 항의가 플레이 영역에 없다면, 주요 음모에 위협을 2만큼 놓습니다."},{"id":"27176","name":"뒷골목 털이","en":"Back Alley Burglary","type":"side","enc":true,"set":"Community Service","unique":false,"boost":3,"start":2,"startStar":true,"surge":1,"tr":[],"victory":1,"traits":[],"text":"쇄도.\n승점 1. <i>(격파되면, 이 카드를 승점 구역에 더합니다.)</i>\n<b>강제 반응</b>: 당신이 이 음모를 저지한 후, [physical] 자원을 소모하거나 당신의 손에서 무작위로 카드 1장을 버리는 것 중 하나를 선택합니다."},{"id":"27177","name":"나무 위의 고양이","en":"Cat in a Tree","type":"side","enc":true,"set":"Community Service","unique":false,"boost":3,"start":3,"startStar":true,"surge":1,"tr":[],"victory":1,"traits":[],"text":"쇄도.\n승점 1. <i>(격파되면, 이 카드를 승점 구역에 더합니다.)</i>\n이 음모를 저지하기 위한 추가 비용으로, 간접 피해 2점을 입습니다."},{"id":"27178","name":"부하들의 강탈","en":"Henchmen Heist","type":"side","enc":true,"set":"Community Service","unique":false,"boost":3,"start":3,"startStar":true,"surge":1,"tr":[],"victory":1,"traits":[],"text":"쇄도.\n승점 1. <i>(격파되면, 이 카드를 승점 구역에 더합니다.)</i>\n<b>강제 반응</b>: 이 음모에서 위협이 제거된 후, 그만큼의 위협을 주요 음모에 놓습니다."},{"id":"27179","name":"탈선","en":"Off the Rails","type":"side","enc":true,"set":"Community Service","unique":false,"boost":3,"start":3,"startStar":true,"surge":1,"tr":[],"victory":1,"traits":[],"text":"쇄도.\n승점 1. <i>(격파되면, 이 카드를 승점 구역에 더합니다.)</i>\n<b>강제 난입</b>: 빌런 페이즈가 시작될 때, 이 카드에 속도 카운터를 1만큼 놓습니다. 이 카드에 속도 카운터가 2개 이상 있다면, 이 카드를 게임에서 제거하고 각 플레이어의 덱 맨 위에서 카드 3장을 버립니다."},{"id":"27180","name":"잔해 속 구조","en":"Rubble Rescue","type":"side","enc":true,"set":"Community Service","unique":false,"boost":3,"start":5,"startStar":true,"surge":1,"tr":[],"victory":1,"traits":[],"text":"쇄도.\n승점 1. <i>(격파되면, 이 카드를 승점 구역에 더합니다.)</i>\n<b>난입</b>: 캐릭터가 이 부가 음모를 상대로 기본 저지를 할 때, <i>(그 캐릭터는)</i> 저지 수치 대신 공격 수치를 사용할 수 있습니다."},{"id":"27181","name":"밀고자는 대가를 치른다","en":"Snitches Get Stitches","type":"attachment","enc":true,"set":"Snitches get Stitches","unique":false,"boost":3,"tr":[],"victory":-1,"traits":[],"text":"승점 -1.\n베놈 (에디 브록)에게 장착합니다. 그럴 수 없다면, 이 카드는 쇄도를 얻습니다.\n<b>강제 난입</b>: 빌런이 공격할 때, 그 빌런은 베놈을 공격합니다. 그 공격으로 베놈이 격파되면, 베놈과 이 카드를 승점 구역에 더합니다.\n<b>행동</b>: 베놈을 소진하고 같은 유형의 자원 2개를 소모 → 이 카드를 버림."},{"id":"27182a","name":"소형 다트","en":"Compact Darts","type":"upgrade","enc":false,"unique":false,"cls":"Campaign","tr":["S.H.I.E.L.D","TECH"],"permanent":1,"setupCard":1,"traits":["S.H.I.E.L.D","과학"],"text":"사전 준비. 영속.\n<b>히어로 반응</b>: 당신의 히어로가 공격한 후, 이 카드에서 다트 카운터를 1만큼 제거 → 적 하나에게 피해 1점을 입힘.\n<b>일상 행동</b>: 아무 유형의 자원 1개를 소모 → 이 카드에 다트 카운터를 3만큼 놓음. (라운드마다 1회 제한.)"},{"id":"27182b","name":"소형 다트","en":"Compact Darts","type":"upgrade","enc":false,"unique":false,"cls":"Campaign","tr":["ENHANCED","S.H.I.E.L.D","TECH"],"permanent":1,"traits":["개량","S.H.I.E.L.D","과학"],"text":"영속.\n<b>히어로 반응</b>: 당신의 히어로가 공격한 후, 이 카드에서 다트 카운터를 1만큼 제거 → 서로 다른 적을 2명까지 선택해 각각 피해 1점을 입힘.\n<b>일상 행동</b>: 아무 유형의 자원 1개를 소모 → 이 카드에 다트 카운터를 3만큼 놓음. (라운드마다 1회 제한.)"},{"id":"27183a","name":"충격 완화 슈트","en":"Impact-Dampening Suit","type":"upgrade","enc":false,"unique":false,"cls":"Campaign","tr":["S.H.I.E.L.D","TECH"],"permanent":1,"setupCard":1,"traits":["S.H.I.E.L.D","과학"],"text":"사전 준비. 영속.\n당신의 아이덴티티는 생명력 +2를 받습니다.\n<b>히어로 난입</b>: 빌런 페이즈가 시작될 때, 아무 유형의 자원 1개를 소모 → 페이즈가 끝날 때까지, 당신의 히어로가 각 적의 공격으로 입는 피해를 1만큼 감소."},{"id":"27183b","name":"충격 완화 슈트","en":"Impact-Dampening Suit","type":"upgrade","enc":false,"unique":false,"cls":"Campaign","tr":["ENHANCED","S.H.I.E.L.D","TECH"],"permanent":1,"traits":["개량","S.H.I.E.L.D","과학"],"text":"영속.\n당신의 아이덴티티는 생명력 +3을 받습니다.\n<b>히어로 난입</b>: 당신의 히어로가 적의 공격으로 피해를 입으려 할 때, 당신의 덱 맨 위에서 카드 1장을 버림 → 그 피해에서 1점을 방지."},{"id":"27184a","name":"레이저 고글","en":"Laser Goggles","type":"upgrade","enc":false,"unique":false,"cls":"Campaign","tr":["S.H.I.E.L.D","TECH"],"permanent":1,"setupCard":1,"traits":["S.H.I.E.L.D","과학"],"text":"사전 준비. 영속.\n당신의 히어로는 저지 -1을 받습니다.\n당신의 히어로는 공격 +1을 받고, 당신의 히어로의 기본 공격은 압살을 얻습니다."},{"id":"27184b","name":"레이저 고글","en":"Laser Goggles","type":"upgrade","enc":false,"unique":false,"cls":"Campaign","tr":["ENHANCED","S.H.I.E.L.D","TECH"],"permanent":1,"traits":["개량","S.H.I.E.L.D","과학"],"text":"영속.\n당신의 히어로는 저지 -1을 받습니다.\n당신의 히어로는 공격 +2를 받고, 당신의 히어로의 기본 공격은 압살과 관통을 얻습니다."},{"id":"27185a","name":"추진 건틀렛","en":"Propulsion Gauntlet","type":"upgrade","enc":false,"unique":false,"cls":"Campaign","tr":["S.H.I.E.L.D","TECH"],"permanent":1,"setupCard":1,"traits":["S.H.I.E.L.D","과학"],"text":"사전 준비. 영속.\n<b>히어로 행동</b>: 추진 건틀렛을 소진하고 간접 피해 2점을 입음 → 당신의 히어로를 준비."},{"id":"27185b","name":"추진 건틀렛","en":"Propulsion Gauntlet","type":"upgrade","enc":false,"unique":false,"cls":"Campaign","tr":["ENHANCED","S.H.I.E.L.D","TECH"],"permanent":1,"traits":["개량","S.H.I.E.L.D","과학"],"text":"영속.\n<b>히어로 행동</b>: 추진 건틀렛을 소진하고 간접 피해 2점을 입음 → 당신의 히어로를 준비. 페이즈가 끝날 때까지 당신의 히어로는 저지 +1, 공격 +1, 방어 +1을 받음."},{"id":"27186a","name":"망막 디스플레이","en":"Retinal Display","type":"upgrade","enc":false,"unique":false,"cls":"Campaign","tr":["S.H.I.E.L.D","TECH"],"permanent":1,"setupCard":1,"traits":["S.H.I.E.L.D","과학"],"text":"사전 준비. 영속.\n당신의 히어로의 기본 저지 능력<i>(저지)</i>은 위협이 가장 많은 음모에서만 위협을 제거할 수 있습니다.\n당신의 히어로는 저지 +1을 받고, 당신의 히어로의 기본 저지는 위기 아이콘<i>([crisis])</i>을 무시합니다."},{"id":"27186b","name":"망막 디스플레이","en":"Retinal Display","type":"upgrade","enc":false,"unique":false,"cls":"Campaign","tr":["ENHANCED","S.H.I.E.L.D","TECH"],"permanent":1,"traits":["개량","S.H.I.E.L.D","과학"],"text":"영속.\n당신의 히어로의 기본 저지 능력<i>(저지)</i>은 위협이 가장 많은 음모에서만 위협을 제거할 수 있습니다.\n당신의 히어로는 저지 +2를 받고, 당신의 히어로의 기본 저지는 위기 아이콘<i>([crisis])</i>과 순찰 키워드를 무시합니다."},{"id":"27187a","name":"전격 너클","en":"Shock Knuckles","type":"upgrade","enc":false,"unique":false,"cls":"Campaign","tr":["S.H.I.E.L.D","TECH"],"permanent":1,"setupCard":1,"traits":["S.H.I.E.L.D","과학"],"text":"사전 준비. 영속.\n<b>히어로 반응</b>: 당신의 히어로가 적을 상대로 기본 공격을 한 후, 조우 덱 맨 위에서 카드 1장을 버립니다. 이렇게 버려진 강화 아이콘<i>([boost])</i>이 없다면, 그 적을 기절시킵니다."},{"id":"27187b","name":"전격 너클","en":"Shock Knuckles","type":"upgrade","enc":false,"unique":false,"cls":"Campaign","tr":["ENHANCED","S.H.I.E.L.D","TECH"],"permanent":1,"traits":["개량","S.H.I.E.L.D","과학"],"text":"영속.\n당신의 히어로가 공격 +1을 받습니다.\n<b>히어로 반응</b>: 당신의 히어로가 적을 상대로 기본 공격을 한 후, 조우 덱 맨 위에서 카드 1장을 버립니다. 이렇게 버려진 강화 아이콘<i>([boost])</i>이 1개 이하라면, 그 적을 기절시킵니다."},{"id":"27188a","name":"파동 팔찌","en":"Wave Bracers","type":"upgrade","enc":false,"unique":false,"cls":"Campaign","tr":["S.H.I.E.L.D","TECH"],"permanent":1,"setupCard":1,"traits":["S.H.I.E.L.D","과학"],"text":"사전 준비. 영속.\n당신의 히어로는 공격 -1을 받습니다.\n당신의 히어로는 방어 +1을 받고, 반격 1과 의연을 얻습니다."},{"id":"27188b","name":"파동 팔찌","en":"Wave Bracers","type":"upgrade","enc":false,"unique":false,"cls":"Campaign","tr":["ENHANCED","S.H.I.E.L.D","TECH"],"permanent":1,"traits":["개량","S.H.I.E.L.D","과학"],"text":"영속.\n당신의 히어로는 공격 -1을 받습니다.\n당신의 히어로는 방어 +2를 받고, 반격 1과 견고를 얻습니다."},{"id":"27189a","name":"손목 내비게이터","en":"Wrist Navigators","type":"upgrade","enc":false,"unique":false,"cls":"Campaign","tr":["S.H.I.E.L.D","TECH"],"permanent":1,"setupCard":1,"traits":["S.H.I.E.L.D","과학"],"text":"사전 준비. 영속.\n<b>강제 반응</b>: 하수인이나 부가 음모가 플레이 영역에 들어온 후, 손목 내비게이터를 그 카드에 장착합니다.\n<b>난입</b>: 장착된 카드가 격파될 때, 카드 1장을 뽑습니다. <i>(이 카드를 당신의 플레이 영역으로 되돌립니다.)</i>"},{"id":"27189b","name":"손목 내비게이터","en":"Wrist Navigators","type":"upgrade","enc":false,"unique":false,"cls":"Campaign","tr":["ENHANCED","S.H.I.E.L.D","TECH"],"permanent":1,"traits":["개량","S.H.I.E.L.D","과학"],"text":"영속.\n<b>강제 반응</b>: 하수인이나 부가 음모가 플레이 영역에 들어온 후, 손목 내비게이터를 그 카드에 장착합니다.\n<b>난입</b>: 장착된 카드가 격파될 때, 카드 2장을 뽑고, 그러고 나서 당신의 손에서 카드 1장을 버립니다."},{"id":"27190","name":"베놈","en":"* Venom","type":"ally","enc":false,"sub":"에디 브록","unique":true,"hp":6,"atk":3,"atkStar":true,"thw":2,"thwStar":true,"cost":4,"hazard":1,"res":"G","cls":"Basic","tr":["SYMBIOTE"],"traits":["심비오트"],"text":"<b>반응</b>: 당신이 조우 카드를 공개한 후, 베놈에게 피해 1점을 입힘 → 그 카드의 강화 영역에 있는 아이콘<i>([star]와 [boost])</i>의 수만큼 적 하나에게 피해를 입힘.","star":true},{"id":"27191","name":"심비오트 슈트","en":"Symbiote Suit","type":"upgrade","enc":false,"unique":false,"cost":4,"hazard":1,"res":"G","cls":"Basic","tr":["SYMBIOTE"],"maxDeck":1,"traits":["심비오트"],"text":"덱마다 최대 1장.\n당신의 아이덴티티는 각 기본 능력 +1, 손 크기 +1, 생명력 +10을 받습니다."}]});
